INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K1-2-u3-C1','kor',1,2,'u3',2,'바른 자세로 발표하기 — 허리를 펴고 바르게 서서, 알맞은 크기의 목소리로 또박또박, 듣는 사람을 바라보며 말끝을 흐리지 않고 끝까지 분명하게 말하기, 발표 전에 말할 내용 생각하기',ARRAY['2국01-04']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K1-2-u3-C2','kor',1,2,'u3',2,'바른 자세로 듣기 — 말하는 사람을 바라보며 귀 기울여 듣기, 떠들거나 딴짓하지 않기, 궁금한 점을 생각하며 듣기, 고개를 끄덕이거나 미소 짓기',ARRAY['2국01-04']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K1-2-u3-C3','kor',1,2,'u3',4,'경험한 일을 정리해 발표하기 — 오늘 아침에 있었던 일을 무슨 일·어디에서·어떻게 되었는지 물음으로 정리해 한 문장으로 발표하기, 작은 일도 발표할 거리',ARRAY['2국01-04']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K1-2-u3-C4','kor',1,2,'u3',6,'기억에 남는 일을 문장과 그림으로 — 우리 반이 함께 한 일을 느낌(재미있었던·슬펐던·놀랐던 일)으로 정리, 「우리는 무엇을 어떻게 했다」 문장으로 말하기, 한 장면을 골라 그리기',ARRAY['2국03-04']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K1-2-u3-C5','kor',1,2,'u3',8,'그림일기를 쓰는 방법 알기 — 날짜와 요일·날씨, 그림, 글(기억에 남는 일과 생각이나 느낌); 찬호 그림일기 읽기, 잘못 쓴 그림일기 고칠 점 찾기',ARRAY['2국03-04']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K1-2-u3-C6','kor',1,2,'u3',10,'경험한 일을 그림일기로 쓰기 — 어제 일을 아침·낮·저녁으로 떠올리기, 언제·어디에서·누구와·무슨 일·느낌으로 정리, 날씨 재미있게 쓰기, 점검하고 고쳐 쓰기, 문장에 「무엇을」 넣기',ARRAY['2국03-04']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K1-2-u3-C7','kor',1,2,'u3',12,'글과 그림으로 나타내고 감상하기 — 친구와 있었던 일을 표로 정리, 한 장면 골라 글과 그림으로, 제목 붙이기, 전시하고 칭찬하며 감상 나누기',ARRAY['2국06-02']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u3-X01','kor',1,'u3',ARRAY['K1-2-u3-C1']::text[],'목소리만 크게 지르면 잘 말하는 것이라고 여기거나, 작은 목소리로 말끝을 흐린다 (「제가 좋아하는 색은 파란색…….」)','「소리를 지르면 또렷해지나요?」 알맞은 크기로 끝까지 분명하게 말하는 것과 견주어 보게 하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u3-X02','kor',1,'u3',ARRAY['K1-2-u3-C1']::text[],'듣는 사람을 보지 않고 바닥·칠판을 보거나 허리를 굽힌 채 말한다','말하는 사람 앞에 친구를 세우고 「누구를 보고 말하나요?」 되묻기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u3-X03','kor',1,'u3',ARRAY['K1-2-u3-C1']::text[],'발표하기 전에 무엇을 말할지 생각하지 않고 일어난다','「무엇을 말할지 한 문장으로 먼저 정해 보자」 — 남자아이가 탐험가를 알아본 장면 떠올리기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u3-X04','kor',1,'u3',ARRAY['K1-2-u3-C2']::text[],'들으면서 떠들거나 딴짓을 한다 (「어제 말이야…….」·「예쁜 그림을 그려야지.」)','「떠들면 말하는 사람이 말을 잊을 수 있어요」 — 말하는 사람을 바라보며 듣게 하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u3-X05','kor',1,'u3',ARRAY['K1-2-u3-C2']::text[],'끝까지 듣지 않고 끼어들거나, 잘못 듣는 친구를 나무란다','나무라는 말 대신 「말하는 사람을 바라보며 들어야 해.」처럼 알려 주는 말로 바꾸어 보게 하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u3-X06','kor',1,'u3',ARRAY['K1-2-u3-C3','K1-2-u3-C5']::text[],'특별한 큰 일이 있어야만 발표나 일기의 글감이 된다고 여긴다','「나는 ○○을/를 먹었다.」처럼 아침에 있었던 작은 일 하나를 함께 떠올리기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u3-X07','kor',1,'u3',ARRAY['K1-2-u3-C3','K1-2-u3-C6']::text[],'「재미있었다」 한마디만 말하거나 쓴다 — 무슨 일·어디에서·어떻게 되었는지가 빠진다','물음(무슨 일·어디에서·어떻게 되었지?)을 손가락으로 세며 빠진 칸을 채우게 하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u3-X08','kor',1,'u3',ARRAY['K1-2-u3-C3','K1-2-u3-C7']::text[],'발표 점검이나 작품 감상을 「누가 제일 잘했나」 가리기로 여긴다','「내 발표에서 잘된 것 하나·고칠 것 하나」만 말하게 하고, 친구에게는 칭찬할 점을 찾게 하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u3-X09','kor',1,'u3',ARRAY['K1-2-u3-C4']::text[],'있었던 일과 느낌을 안 맞게 잇는다 (전학 간 일을 재미있었던 일에)','「그때 어떤 마음이었나요?」 느낌을 먼저 고르고 일을 붙이게 하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u3-X10','kor',1,'u3',ARRAY['K1-2-u3-C4','K1-2-u3-C6','K1-2-u3-C7']::text[],'그림을 잘 그리기·예쁘게 색칠하기 겨루기로 여긴다','「그림만 보고 무슨 일인지 알 수 있나요?」 — 미술 활동이 아니라 있었던 일이 보이면 된다고 짚어 주기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u3-X11','kor',1,'u3',ARRAY['K1-2-u3-C5','K1-2-u3-C6']::text[],'날짜·요일·날씨를 빠뜨리거나 자리를 틀린다 (98쪽 일기의 빈 날씨)','맨 윗줄을 손가락으로 짚으며 「날짜 · 요일 · 날씨」 세 가지를 차례로 세어 보게 하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u3-X12','kor',1,'u3',ARRAY['K1-2-u3-C5']::text[],'그림일기에 들어갈 것이 아닌 것(이름·인사·식단·시간표·준비물)을 넣는다','「이건 내가 겪은 일인가요, 알려 주는 글인가요?」 107쪽 색칠하기로 견주기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u3-X13','kor',1,'u3',ARRAY['K1-2-u3-C4','K1-2-u3-C6','K1-2-u3-C7']::text[],'여러 장면을 다 그리려 하거나 그림과 글이 서로 다른 일을 담는다','「가장 기억에 남는 한 장면은?」 글을 먼저 읽고 그 글에 맞는 그림인지 짚어 보게 하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u3-X14','kor',1,'u3',ARRAY['K1-2-u3-C5','K1-2-u3-C6']::text[],'하루 일을 늘어놓거나 날마다 하는 일을 쓴다 (일어나 밥을 먹고 학교에 가서 공부를 했다)','「그날 새롭게 느낀 일 하나만」 — 늘 하는 일을 지우고 남는 것 찾기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u3-X15','kor',1,'u3',ARRAY['K1-2-u3-C6']::text[],'생각이나 느낌을 쓰지 않거나 「참 재미있었다」 같은 버릇말만 쓴다','「재미있었다」 뒤에 「왜냐하면」을 붙여 무엇이 어떻게 좋았는지 한 번 더 말하게 하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u3-X16','kor',1,'u3',ARRAY['K1-2-u3-C6']::text[],'그림에 시간을 다 써서 정작 글을 못 쓰거나, 언제·어디에서·누가가 빠진 글을 쓴다','「그림은 간단히, 글은 자세히」 — 글 쓸 시간을 먼저 남기게 하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u3-X17','kor',1,'u3',ARRAY['K1-2-u3-C6']::text[],'다 쓴 뒤 다시 읽지 않거나, 친구 일기의 빠진 내용을 알려 주지 못한다','103쪽 점검 물음을 하나씩 읽으며 「예·아니요」를 스스로 고르게 하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u3-X18','kor',1,'u3',ARRAY['K1-2-u3-C7']::text[],'친구 작품을 놀리거나 마음대로 만지는 등 감상 예절을 지키지 않는다','「무엇이 좋았는지」 한 가지를 짚어 말하게 하고 작품에 손대지 않기 약속하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u3-X19','kor',1,'u3',ARRAY['K1-2-u3-C6']::text[],'문장에서 「무엇을」 자리를 빠뜨리거나 다른 말로 채운다 (황새가 먹습니다 → 황새가 물고기를 먹습니다)','「무엇을?」 하고 되물어 빠진 말을 그림에서 찾아 넣게 하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L01_basic#1','kor',1,2,'u3','L01','g1_2_kor_u3_L01_basic','lesson_basic','K1-2-u3-C1',1,'mc','auto','『국어』 81쪽 생각 열기 — 여자아이는 어떤 경험을 떠올리고 있나요?',ARRAY['K1-2-u3-X06']::text[],false,'{"seq":1,"concept":"K1-2-u3-C1","difficulty":1,"kind":"mc","stem":"『국어』 81쪽 생각 열기 — 여자아이는 어떤 경험을 떠올리고 있나요?","options":[{"t":"달리기한 경험","correct":true},{"t":"수영한 경험","mis":"K1-2-u3-X06"},{"t":"생일잔치를 한 경험","mis":"K1-2-u3-X06"}],"explanation":["운동장에서 친구들과 달리기한 경험이에요.","수영이나 생일잔치는 그림에 없어요.","81쪽 맨 위 그림을 떠올려요."],"asset":{"type":"scene","icon":"🏃‍♀️🏁","text":"운동장에서 달리기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L01_basic#2','kor',1,2,'u3','L01','g1_2_kor_u3_L01_basic','lesson_basic','K1-2-u3-C1',1,'mc','auto','『국어』 82쪽 1번 — 그림 ㉮에서 남자아이가 여자아이의 말을 제대로 알아듣지 못한 까닭은?',ARRAY['K1-2-u3-X01','K1-2-u3-X04']::text[],false,'{"seq":2,"concept":"K1-2-u3-C1","difficulty":1,"kind":"mc","stem":"『국어』 82쪽 1번 — 그림 ㉮에서 남자아이가 여자아이의 말을 제대로 알아듣지 못한 까닭은?","options":[{"t":"목소리가 작고 말끝을 흐려서","correct":true},{"t":"목소리가 너무 또렷해서","mis":"K1-2-u3-X01"},{"t":"파란색을 싫어해서","mis":"K1-2-u3-X04"}],"explanation":["목소리가 작아서 잘 들리지 않았고, 말끝을 흐려서 알아듣기 힘들었어요.","또렷하게 말하면 잘 들려요.","남자아이의 생각을 읽어 봐요."],"asset":{"type":"speech","turns":[{"who":"여자아이(㉮)","text":"제가 좋아하는 색은 파란색……."},{"who":"남자아이(생각)","text":"목소리가 작아서 잘 안 들려."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L01_basic#3','kor',1,2,'u3','L01','g1_2_kor_u3_L01_basic','lesson_basic','K1-2-u3-C1',1,'mc','auto','『국어』 82쪽 1번 — 그림 ㉯의 여자아이처럼 발표하면 좋은 점은?',ARRAY['K1-2-u3-X03','K1-2-u3-X02']::text[],false,'{"seq":3,"concept":"K1-2-u3-C1","difficulty":1,"kind":"mc","stem":"『국어』 82쪽 1번 — 그림 ㉯의 여자아이처럼 발표하면 좋은 점은?","options":[{"t":"듣는 사람이 뜻을 알아듣기 쉬워요","correct":true},{"t":"발표가 빨리 끝나요","mis":"K1-2-u3-X03"},{"t":"아무도 나를 보지 않아요","mis":"K1-2-u3-X02"}],"explanation":["말하는 사람은 뜻을 잘 전하고, 듣는 사람은 알아듣기 쉬워요.","빨리 끝내는 것이 좋은 점이 아니에요.","남자아이의 생각을 읽어 봐요."],"asset":{"type":"speech","turns":[{"who":"여자아이(㉯)","text":"제가 좋아하는 색은 파란색입니다."},{"who":"남자아이(생각)","text":"파란색을 좋아하는구나."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L01_basic#4','kor',1,2,'u3','L01','g1_2_kor_u3_L01_basic','lesson_basic','K1-2-u3-C3',1,'mc','auto','『국어』 83쪽 3번 — 자신이 경험한 일을 표현하는 방법으로 알맞은 것은?',ARRAY['K1-2-u3-X06']::text[],false,'{"seq":4,"concept":"K1-2-u3-C3","difficulty":1,"kind":"mc","stem":"『국어』 83쪽 3번 — 자신이 경험한 일을 표현하는 방법으로 알맞은 것은?","options":[{"t":"그날 경험한 일을 일기에 쓴다","correct":true},{"t":"경험한 일을 그냥 잊어버린다","mis":"K1-2-u3-X06"},{"t":"남의 일기를 몰래 읽는다","mis":"K1-2-u3-X06"}],"explanation":["말하기, 일기 쓰기, 사진이나 그림으로 발표하기가 있어요.","잊어버리거나 남의 일기를 읽는 것은 표현하는 방법이 아니에요.","83쪽 3번을 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L01_basic#5','kor',1,2,'u3','L01','g1_2_kor_u3_L01_basic','lesson_basic','K1-2-u3-C1',2,'ox','auto','『국어』 82쪽 — 발표할 때에는 바르게 서서 말끝을 흐리지 않고 끝까지 분명하게 말해야 해요.',ARRAY['K1-2-u3-X01']::text[],false,'{"seq":5,"concept":"K1-2-u3-C1","difficulty":2,"kind":"ox","stem":"『국어』 82쪽 — 발표할 때에는 바르게 서서 말끝을 흐리지 않고 끝까지 분명하게 말해야 해요.","answer":"O","reason_options":[{"t":"그래야 듣는 사람이 잘 알아들을 수 있으니까","correct":true},{"t":"말끝은 흐려도 뜻은 똑같이 전해지니까","mis":"K1-2-u3-X01"}],"mis":"K1-2-u3-X01","explanation":["㉮처럼 말끝을 흐리면 알아듣기 힘들어요.","끝까지 분명하게 말해요.","82쪽 알아 두기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L01_basic#6','kor',1,2,'u3','L01','g1_2_kor_u3_L01_basic','lesson_basic','K1-2-u3-C2',2,'mc','auto','『국어』 83쪽 2번 — 친구가 주말에 있었던 일을 이야기할 때 나는 어떻게 들어야 할까요?',ARRAY['K1-2-u3-X05','K1-2-u3-X04']::text[],false,'{"seq":6,"concept":"K1-2-u3-C2","difficulty":2,"kind":"mc","stem":"『국어』 83쪽 2번 — 친구가 주말에 있었던 일을 이야기할 때 나는 어떻게 들어야 할까요?","options":[{"t":"친구를 바라보며 끝까지 들어요","correct":true},{"t":"내 이야기만 계속해요","mis":"K1-2-u3-X05"},{"t":"다른 곳을 보며 들어요","mis":"K1-2-u3-X04"}],"explanation":["말하는 친구를 바라보며 끝까지 들어요.","끼어들거나 딴 곳을 보면 이야기를 놓쳐요.","듣는 자세도 점검해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L01_basic#7','kor',1,2,'u3','L01','g1_2_kor_u3_L01_basic','lesson_basic','K1-2-u3-C3',2,'mc','auto','『국어』 83쪽 2번 — 「아빠와 시장에 갔어.」는 무엇을 이야기한 것인가요?',ARRAY['K1-2-u3-X07','K1-2-u3-X06']::text[],false,'{"seq":7,"concept":"K1-2-u3-C3","difficulty":2,"kind":"mc","stem":"『국어』 83쪽 2번 — 「아빠와 시장에 갔어.」는 무엇을 이야기한 것인가요?","options":[{"t":"주말에 있었던 일","correct":true},{"t":"내일 할 일","mis":"K1-2-u3-X07"},{"t":"책에서 읽은 이야기","mis":"K1-2-u3-X06"}],"explanation":["주말에 있었던 일을 친구에게 이야기했어요.","내가 겪은 일이라 경험한 일이에요.","83쪽 그림 속 말을 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L01_basic#8','kor',1,2,'u3','L01','g1_2_kor_u3_L01_basic','lesson_basic','K1-2-u3-C3',2,'match','auto','『국어』 83쪽 3번 — 표현하는 방법과 알맞은 모습을 이어 보세요.','{}'::text[],false,'{"seq":8,"concept":"K1-2-u3-C3","difficulty":2,"kind":"match","stem":"『국어』 83쪽 3번 — 표현하는 방법과 알맞은 모습을 이어 보세요.","pairs":[{"l":"말로","r":"다른 사람에게 자신의 경험을 말한다"},{"l":"글로","r":"그날 경험한 일을 일기에 쓴다"},{"l":"사진이나 그림으로","r":"사진이나 그림을 활용해 발표한다"}],"mis":"K1-2-u3-X07","explanation":["말로 하면 말하기, 글로 하면 일기예요.","사진이나 그림을 보여 주며 발표할 수도 있어요.","83쪽 3번의 세 칸이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L01_basic#9','kor',1,2,'u3','L01','g1_2_kor_u3_L01_basic','lesson_basic','K1-2-u3-C1',2,'mc','auto','『국어』 82쪽 — 그림 ㉮와 ㉯의 여자아이는 무엇이 다른가요?',ARRAY['K1-2-u3-X01']::text[],false,'{"seq":9,"concept":"K1-2-u3-C1","difficulty":2,"kind":"mc","stem":"『국어』 82쪽 — 그림 ㉮와 ㉯의 여자아이는 무엇이 다른가요?","options":[{"t":"㉯는 「파란색입니다.」처럼 끝까지 분명하게 말했어요","correct":true},{"t":"㉮가 더 분명하게 말했어요","mis":"K1-2-u3-X01"},{"t":"㉯는 말끝을 흐렸어요","mis":"K1-2-u3-X01"}],"explanation":["㉮는 「파란색…….」 하고 말끝을 흐렸어요.","㉯는 끝까지 분명하게 말해 잘 들렸어요.","두 말풍선을 견주어 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L01_basic#10','kor',1,2,'u3','L01','g1_2_kor_u3_L01_basic','lesson_basic','K1-2-u3-C3',3,'mc','auto','경험한 일을 사진이나 그림을 활용해 발표하면 좋은 점은?',ARRAY['K1-2-u3-X03','K1-2-u3-X10']::text[],false,'{"seq":10,"concept":"K1-2-u3-C3","difficulty":3,"kind":"mc","stem":"경험한 일을 사진이나 그림을 활용해 발표하면 좋은 점은?","options":[{"t":"듣는 사람이 장면을 더 잘 떠올릴 수 있어요","correct":true},{"t":"말을 하지 않아도 돼요","mis":"K1-2-u3-X03"},{"t":"그림만 예쁘면 끝이에요","mis":"K1-2-u3-X10"}],"explanation":["사진이나 그림이 있으면 무슨 일이었는지 더 잘 보여요.","그래도 말로 설명하는 것이 필요해요.","83쪽 3번의 셋째 칸이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
