INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L01_challenge#2','kor',1,2,'u3','L01','g1_2_kor_u3_L01_challenge','lesson_challenge','K1-2-u3-C2',2,'mc','auto','친구가 발표할 때 바른 자세로 듣는 모습은?',ARRAY['K1-2-u3-X04','K1-2-u3-X05']::text[],false,'{"seq":2,"concept":"K1-2-u3-C2","difficulty":2,"kind":"mc","stem":"친구가 발표할 때 바른 자세로 듣는 모습은?","options":[{"t":"말하는 친구를 바라보며 귀 기울여 들어요","correct":true},{"t":"짝과 이야기하며 들어요","mis":"K1-2-u3-X04"},{"t":"친구가 말을 마치기 전에 끼어들어요","mis":"K1-2-u3-X05"}],"explanation":["말하는 사람을 바라보며 귀 기울여 들어요.","떠들거나 끼어들면 잘 들을 수 없어요.","듣는 자세를 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L01_challenge#3','kor',1,2,'u3','L01','g1_2_kor_u3_L01_challenge','lesson_challenge','K1-2-u3-C1',3,'error','auto','친구가 「제가 좋아하는 색은 파란색…….」이라고 발표했어요. 무엇이 잘못되었나요?',ARRAY['K1-2-u3-X01','K1-2-u3-X03']::text[],false,'{"seq":3,"concept":"K1-2-u3-C1","difficulty":3,"kind":"error","stem":"친구가 「제가 좋아하는 색은 파란색…….」이라고 발표했어요. 무엇이 잘못되었나요?","options":[{"t":"말끝을 흐렸어요 — 「파란색입니다.」처럼 끝까지 분명하게 말해요","correct":true,"mis_target":"K1-2-u3-X01"},{"t":"잘 말했어요 — 듣는 사람이 다 알아들어요","mis":"K1-2-u3-X01"},{"t":"더 빨리 말해야 해요","mis":"K1-2-u3-X03"}],"explanation":["말끝을 흐리면 듣는 사람이 알아듣기 힘들어요.","끝까지 분명하게 말하면 뜻이 잘 전해져요.","82쪽 그림 ㉮예요."],"asset":{"type":"speech","turns":[{"who":"여자아이(㉮)","text":"제가 좋아하는 색은 파란색……."},{"who":"남자아이(생각)","text":"목소리가 작아서 잘 안 들려."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L01_challenge#4','kor',1,2,'u3','L01','g1_2_kor_u3_L01_challenge','lesson_challenge','K1-2-u3-C1',3,'mc','auto','목소리를 있는 힘껏 크게 지르면 잘 발표한 것일까요?',ARRAY['K1-2-u3-X01','K1-2-u3-X02']::text[],false,'{"seq":4,"concept":"K1-2-u3-C1","difficulty":3,"kind":"mc","stem":"목소리를 있는 힘껏 크게 지르면 잘 발표한 것일까요?","options":[{"t":"아니에요 — 알맞은 크기의 목소리로 분명하게 말해야 해요","correct":true},{"t":"네 — 목소리는 클수록 좋아요","mis":"K1-2-u3-X01"},{"t":"네 — 듣는 사람은 생각하지 않아도 돼요","mis":"K1-2-u3-X02"}],"explanation":["자신 있게 말하기는 목소리만 크게 하는 것이 아니에요.","알맞은 크기와 분명한 발음이 중요해요.","지도서 유의점이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L01_challenge#5','kor',1,2,'u3','L01','g1_2_kor_u3_L01_challenge','lesson_challenge','K1-2-u3-C3',3,'ox','auto','특별한 일이 아니어도 주말에 있었던 일을 이야기할 수 있어요.',ARRAY['K1-2-u3-X06']::text[],false,'{"seq":5,"concept":"K1-2-u3-C3","difficulty":3,"kind":"ox","stem":"특별한 일이 아니어도 주말에 있었던 일을 이야기할 수 있어요.","answer":"O","reason_options":[{"t":"「아빠와 시장에 갔어.」처럼 가까운 일도 내가 겪은 경험이니까","correct":true},{"t":"아주 특별한 일만 경험이라고 할 수 있으니까","mis":"K1-2-u3-X06"}],"mis":"K1-2-u3-X06","explanation":["어제, 오늘 아침처럼 가까운 일도 경험이에요.","특별하지 않아도 이야기할 거리가 돼요.","83쪽 2번이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L01_challenge#6','kor',1,2,'u3','L01','g1_2_kor_u3_L01_challenge','lesson_challenge','K1-2-u3-C2',3,'error','auto','친구가 발표할 때 짝에게 「어제 말이야…….」 하고 말을 걸었어요. 무엇이 잘못되었나요?',ARRAY['K1-2-u3-X04','K1-2-u3-X05']::text[],false,'{"seq":6,"concept":"K1-2-u3-C2","difficulty":3,"kind":"error","stem":"친구가 발표할 때 짝에게 「어제 말이야…….」 하고 말을 걸었어요. 무엇이 잘못되었나요?","options":[{"t":"떠들면 발표를 들을 수 없어요 — 말하는 사람을 바라보며 들어요","correct":true,"mis_target":"K1-2-u3-X04"},{"t":"잘했어요 — 짝과 이야기하면 좋아요","mis":"K1-2-u3-X04"},{"t":"발표하는 친구를 크게 나무라야 해요","mis":"K1-2-u3-X05"}],"explanation":["떠들면 나도 못 듣고 다른 친구도 방해해요.","말하는 사람을 바라보며 들어요.","86쪽 그림을 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L01_challenge#7','kor',1,2,'u3','L01','g1_2_kor_u3_L01_challenge','lesson_challenge','K1-2-u3-C1',3,'match','auto','『국어』 82쪽 — 그림과 말을 이어 보세요.','{}'::text[],false,'{"seq":7,"concept":"K1-2-u3-C1","difficulty":3,"kind":"match","stem":"『국어』 82쪽 — 그림과 말을 이어 보세요.","pairs":[{"l":"㉮의 여자아이","r":"제가 좋아하는 색은 파란색……."},{"l":"㉯의 여자아이","r":"제가 좋아하는 색은 파란색입니다."},{"l":"㉮의 남자아이 생각","r":"목소리가 작아서 잘 안 들려."}],"mis":"K1-2-u3-X01","explanation":["㉮는 말끝을 흐렸고, ㉯는 끝까지 말했어요.","그래서 ㉮의 남자아이는 잘 못 들었어요.","두 그림을 견주어 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L01_challenge#8','kor',1,2,'u3','L01','g1_2_kor_u3_L01_challenge','lesson_challenge','K1-2-u3-C1',4,'sa','auto','『국어』 82쪽 — 그림 ㉯의 여자아이가 좋아하는 색은 무엇인가요?','{}'::text[],false,'{"seq":8,"concept":"K1-2-u3-C1","difficulty":4,"kind":"sa","stem":"『국어』 82쪽 — 그림 ㉯의 여자아이가 좋아하는 색은 무엇인가요?","answer":["파란색","파랑","파란 색","파랑색"],"explanation":["「제가 좋아하는 색은 파란색입니다.」라고 했어요.","끝까지 분명하게 말해서 잘 알 수 있어요.","말풍선을 읽어 봐요."],"asset":{"type":"speech","turns":[{"who":"여자아이(㉯)","text":"제가 좋아하는 색은 파란색입니다."},{"who":"남자아이(생각)","text":"파란색을 좋아하는구나."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L01_challenge#9','kor',1,2,'u3','L01','g1_2_kor_u3_L01_challenge','lesson_challenge','K1-2-u3-C3',4,'essay','teacher','『국어』 83쪽 2번 — 주말에 있었던 일을 한 문장으로 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K1-2-u3-C3","difficulty":4,"kind":"essay","stem":"『국어』 83쪽 2번 — 주말에 있었던 일을 한 문장으로 쓰세요.","answer_guide":{"answer":"예: 아빠와 시장에 갔다. / 동생과 놀이터에서 그네를 탔다. — 내가 겪은 일이 한 문장으로 드러나면 맞아요.","scoring_points":["내가 겪은 일인가","한 문장으로 끝까지 썼는가","무엇을 했는지 드러나는가"]},"explanation":["「아빠와 시장에 갔어.」가 본보기예요.","특별한 일이 아니어도 돼요.","누구와 무엇을 했는지 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L01_challenge#10','kor',1,2,'u3','L01','g1_2_kor_u3_L01_challenge','lesson_challenge','K1-2-u3-C1',4,'essay','teacher','『국어』 82쪽 그림 ㉮의 여자아이에게 발표하는 방법을 알려 주는 말을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K1-2-u3-C1","difficulty":4,"kind":"essay","stem":"『국어』 82쪽 그림 ㉮의 여자아이에게 발표하는 방법을 알려 주는 말을 쓰세요.","answer_guide":{"answer":"예: 바르게 서서 말끝을 흐리지 말고 끝까지 분명하게 말해 봐. — 끝까지 분명하게·알맞은 목소리가 들어가면 맞아요.","scoring_points":["말끝을 흐리지 않기를 알려 주었는가","알맞은 크기의 목소리를 말했는가","친절하게 알려 주는 말인가"]},"explanation":["㉮는 목소리가 작고 말끝을 흐렸어요.","고칠 점을 친절하게 알려 줘요.","82쪽 알아 두기를 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L02_basic#1','kor',1,2,'u3','L02','g1_2_kor_u3_L02_basic','lesson_basic','K1-2-u3-C1',1,'mc','auto','『국어』 84~85쪽 1번 — 남자아이의 꿈은 무엇인가요?',ARRAY['K1-2-u3-X03']::text[],false,'{"seq":1,"concept":"K1-2-u3-C1","difficulty":1,"kind":"mc","stem":"『국어』 84~85쪽 1번 — 남자아이의 꿈은 무엇인가요?","options":[{"t":"탐험가","correct":true},{"t":"요리사","mis":"K1-2-u3-X03"},{"t":"소방관","mis":"K1-2-u3-X03"}],"explanation":["「제 꿈은 탐험가입니다.」라고 발표했어요.","요리사나 소방관이 아니에요.","발표한 말을 읽어 봐요."],"asset":{"type":"speech","turns":[{"who":"남자아이","text":"제 꿈은 탐험가입니다."},{"who":"친구(생각)","text":"알맞은 크기의 목소리로 또박또박 이야기하네."},{"who":"남자아이","text":"탐험가가 되어 북극을 탐험해 보고 싶습니다."},{"who":"친구(생각)","text":"듣는 사람을 바라보며 말하네."},{"who":"친구(생각)","text":"허리를 펴고 바른 자세로 서서 발표하네."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L02_basic#2','kor',1,2,'u3','L02','g1_2_kor_u3_L02_basic','lesson_basic','K1-2-u3-C1',1,'mc','auto','『국어』 85쪽 2번 — 바른 자세로 발표하는 방법은?',ARRAY['K1-2-u3-X02','K1-2-u3-X01']::text[],false,'{"seq":2,"concept":"K1-2-u3-C1","difficulty":1,"kind":"mc","stem":"『국어』 85쪽 2번 — 바른 자세로 발표하는 방법은?","options":[{"t":"허리를 펴고 바른 자세로 서서 말한다","correct":true},{"t":"허리를 굽히고 바닥을 보며 말한다","mis":"K1-2-u3-X02"},{"t":"소리를 있는 힘껏 지른다","mis":"K1-2-u3-X01"}],"explanation":["허리를 펴고 바르게 서서 말해요.","바닥을 보거나 소리를 지르는 것은 바른 자세가 아니에요.","85쪽 2번이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L02_basic#3','kor',1,2,'u3','L02','g1_2_kor_u3_L02_basic','lesson_basic','K1-2-u3-C2',1,'mc','auto','『국어』 86쪽 3번 — 듣는 자세가 바른 친구는?',ARRAY['K1-2-u3-X04']::text[],false,'{"seq":3,"concept":"K1-2-u3-C2","difficulty":1,"kind":"mc","stem":"『국어』 86쪽 3번 — 듣는 자세가 바른 친구는?","options":[{"t":"발표하는 친구를 바라보며 「친구가 좋아하는 건 뭘까?」 생각하는 친구","correct":true},{"t":"「예쁜 그림을 그려야지.」 하는 친구","mis":"K1-2-u3-X04"},{"t":"「어제 말이야…….」 하는 친구","mis":"K1-2-u3-X04"}],"explanation":["말하는 사람을 바라보며 궁금한 점을 생각하며 들어요.","그림을 그리거나 떠드는 것은 바른 듣기가 아니에요.","86쪽 그림이에요."],"asset":{"type":"speech","turns":[{"who":"발표하는 친구","text":"제가 좋아하는 것은……."},{"who":"바라보며 듣는 친구(생각)","text":"친구가 좋아하는 건 뭘까?"},{"who":"짝에게 말하는 친구","text":"어제 말이야……."},{"who":"그림 그리는 친구(생각)","text":"예쁜 그림을 그려야지."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L02_basic#4','kor',1,2,'u3','L02','g1_2_kor_u3_L02_basic','lesson_basic','K1-2-u3-C2',1,'mc','auto','『국어』 87쪽 — 「예쁜 그림을 그려야지.」 하는 친구에게 해 줄 말은?',ARRAY['K1-2-u3-X04','K1-2-u3-X05']::text[],false,'{"seq":4,"concept":"K1-2-u3-C2","difficulty":1,"kind":"mc","stem":"『국어』 87쪽 — 「예쁜 그림을 그려야지.」 하는 친구에게 해 줄 말은?","options":[{"t":"딴짓하지 말고 들어야 해.","correct":true},{"t":"그림을 더 예쁘게 그려.","mis":"K1-2-u3-X04"},{"t":"너 정말 나빠!","mis":"K1-2-u3-X05"}],"explanation":["딴짓을 하면 말하는 사람의 말을 알아듣지 못해요.","나무라는 말 대신 알려 주는 말을 해요.","87쪽 (3)이에요."],"asset":{"type":"speech","turns":[{"who":"발표하는 친구","text":"제가 좋아하는 것은……."},{"who":"바라보며 듣는 친구(생각)","text":"친구가 좋아하는 건 뭘까?"},{"who":"짝에게 말하는 친구","text":"어제 말이야……."},{"who":"그림 그리는 친구(생각)","text":"예쁜 그림을 그려야지."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L02_basic#5','kor',1,2,'u3','L02','g1_2_kor_u3_L02_basic','lesson_basic','K1-2-u3-C1',2,'match','auto','『국어』 85쪽 2번 — 바른 자세로 발표하는 방법을 이어 보세요.','{}'::text[],false,'{"seq":5,"concept":"K1-2-u3-C1","difficulty":2,"kind":"match","stem":"『국어』 85쪽 2번 — 바른 자세로 발표하는 방법을 이어 보세요.","pairs":[{"l":"🧍 허리를 쭉 편 아이","r":"허리를 펴고 바른 자세로 서서 말한다."},{"l":"🗣️ 또렷하게 말하는 아이","r":"알맞은 크기의 목소리로 또박또박 말한다."},{"l":"👀 친구들을 보는 아이","r":"듣는 사람을 바라보며 말한다."}],"mis":"K1-2-u3-X02","explanation":["허리 펴기, 알맞은 목소리, 듣는 사람 바라보기예요.","세 가지를 모두 지켜요.","85쪽 2번이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L02_basic#6','kor',1,2,'u3','L02','g1_2_kor_u3_L02_basic','lesson_basic','K1-2-u3-C1',2,'mc','auto','『국어』 84쪽 — 남자아이가 발표하기 전에 한 일은?',ARRAY['K1-2-u3-X03']::text[],false,'{"seq":6,"concept":"K1-2-u3-C1","difficulty":2,"kind":"mc","stem":"『국어』 84쪽 — 남자아이가 발표하기 전에 한 일은?","options":[{"t":"꿈을 어떻게 소개할지 생각하고 탐험가가 하는 일을 알아보았어요","correct":true},{"t":"아무 준비 없이 놀았어요","mis":"K1-2-u3-X03"},{"t":"친구의 발표를 대신 외웠어요","mis":"K1-2-u3-X03"}],"explanation":["「내 꿈을 어떻게 소개하면 좋을까?」 생각하고 도서관에서 알아보았어요.","발표 전에 말할 내용을 생각해요.","84쪽 ②·③ 그림이에요."],"asset":{"type":"speech","turns":[{"who":"선생님","text":"다음 시간에는 자신의 꿈에 대해 발표해 볼 거예요."},{"who":"남자아이(생각)","text":"내 꿈을 어떻게 소개하면 좋을까?"},{"who":"남자아이(도서관에서)","text":"탐험가는 무슨 일을 할까?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L02_basic#7','kor',1,2,'u3','L02','g1_2_kor_u3_L02_basic','lesson_basic','K1-2-u3-C2',2,'match','auto','『국어』 87쪽 (3) — 듣는 자세가 바르지 못한 친구와 해 줄 말을 이어 보세요.','{}'::text[],false,'{"seq":7,"concept":"K1-2-u3-C2","difficulty":2,"kind":"match","stem":"『국어』 87쪽 (3) — 듣는 자세가 바르지 못한 친구와 해 줄 말을 이어 보세요.","pairs":[{"l":"「예쁜 그림을 그려야지.」","r":"딴짓하지 말고 들어야 해."},{"l":"「어제 말이야…….」","r":"시끄럽게 떠들면 안 돼."},{"l":"다른 곳을 보는 친구","r":"말하는 사람을 바라보며 들어야 해."}],"mis":"K1-2-u3-X04","explanation":["그림 그리는 친구는 딴짓, 짝에게 말하는 친구는 떠들기예요.","다른 곳을 보면 말을 놓쳐요.","87쪽 (3)이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
