INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L02_basic#9','kor',1,2,'u3','L02','g1_2_kor_u3_L02_basic','lesson_basic','K1-2-u3-C2',2,'ox','auto','들은 내용을 잘 이해했다면 미소를 짓거나 고개를 끄덕일 수 있어요.',ARRAY['K1-2-u3-X04']::text[],false,'{"seq":9,"concept":"K1-2-u3-C2","difficulty":2,"kind":"ox","stem":"들은 내용을 잘 이해했다면 미소를 짓거나 고개를 끄덕일 수 있어요.","answer":"O","reason_options":[{"t":"말하는 사람이 내가 잘 듣고 있음을 알 수 있으니까","correct":true},{"t":"들을 때에는 아무 표정도 지으면 안 되니까","mis":"K1-2-u3-X04"}],"mis":"K1-2-u3-X04","explanation":["고개를 끄덕이면 말하는 사람에게 힘이 돼요.","발표하는 친구의 얼굴을 보며 바른 자세로 들어요.","지도서 141쪽 참고 자료예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L02_basic#10','kor',1,2,'u3','L02','g1_2_kor_u3_L02_basic','lesson_basic','K1-2-u3-C1',3,'mc','auto','자신 있게 말하는 방법으로 가장 알맞은 것은?',ARRAY['K1-2-u3-X01','K1-2-u3-X03']::text[],false,'{"seq":10,"concept":"K1-2-u3-C1","difficulty":3,"kind":"mc","stem":"자신 있게 말하는 방법으로 가장 알맞은 것은?","options":[{"t":"알맞은 크기의 목소리로 발음을 분명하게 해요","correct":true},{"t":"목소리만 아주 크게 해요","mis":"K1-2-u3-X01"},{"t":"빨리 말하고 얼른 앉아요","mis":"K1-2-u3-X03"}],"explanation":["목소리 크기가 알맞고 발음이 분명한 것이 중요해요.","목소리만 크게 하는 것은 아니에요.","지도서 유의점이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L02_challenge#1','kor',1,2,'u3','L02','g1_2_kor_u3_L02_challenge','lesson_challenge','K1-2-u3-C1',2,'mc','auto','「탐험가가 되어 북극을 탐험해 보고 싶습니다.」라고 말할 때 친구들이 칭찬한 점은?',ARRAY['K1-2-u3-X02','K1-2-u3-X01']::text[],false,'{"seq":1,"concept":"K1-2-u3-C1","difficulty":2,"kind":"mc","stem":"「탐험가가 되어 북극을 탐험해 보고 싶습니다.」라고 말할 때 친구들이 칭찬한 점은?","options":[{"t":"듣는 사람을 바라보며 말했어요","correct":true},{"t":"바닥을 보며 말했어요","mis":"K1-2-u3-X02"},{"t":"소리를 질렀어요","mis":"K1-2-u3-X01"}],"explanation":["「듣는 사람을 바라보며 말하네.」라고 칭찬했어요.","바닥을 보거나 소리를 지르지 않았어요.","85쪽 ⑤ 그림이에요."],"asset":{"type":"speech","turns":[{"who":"남자아이","text":"제 꿈은 탐험가입니다."},{"who":"친구(생각)","text":"알맞은 크기의 목소리로 또박또박 이야기하네."},{"who":"남자아이","text":"탐험가가 되어 북극을 탐험해 보고 싶습니다."},{"who":"친구(생각)","text":"듣는 사람을 바라보며 말하네."},{"who":"친구(생각)","text":"허리를 펴고 바른 자세로 서서 발표하네."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L02_challenge#2','kor',1,2,'u3','L02','g1_2_kor_u3_L02_challenge','lesson_challenge','K1-2-u3-C2',2,'mc','auto','『국어』 86쪽 (2) — 듣는 자세가 바른 친구에게 해 줄 칭찬하는 말은?',ARRAY['K1-2-u3-X04']::text[],false,'{"seq":2,"concept":"K1-2-u3-C2","difficulty":2,"kind":"mc","stem":"『국어』 86쪽 (2) — 듣는 자세가 바른 친구에게 해 줄 칭찬하는 말은?","options":[{"t":"궁금한 점을 생각하며 듣고 있구나.","correct":true},{"t":"시끄럽게 떠들고 있구나.","mis":"K1-2-u3-X04"},{"t":"그림을 열심히 그리고 있구나.","mis":"K1-2-u3-X04"}],"explanation":["바라보기·궁금한 점 생각하기·바른 자세로 앉기를 칭찬해요.","떠들거나 그림 그리기는 칭찬할 점이 아니에요.","86쪽 (2)예요."],"asset":{"type":"speech","turns":[{"who":"발표하는 친구","text":"제가 좋아하는 것은……."},{"who":"바라보며 듣는 친구(생각)","text":"친구가 좋아하는 건 뭘까?"},{"who":"짝에게 말하는 친구","text":"어제 말이야……."},{"who":"그림 그리는 친구(생각)","text":"예쁜 그림을 그려야지."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L02_challenge#3','kor',1,2,'u3','L02','g1_2_kor_u3_L02_challenge','lesson_challenge','K1-2-u3-C2',3,'error','auto','「친구가 발표할 때 그림을 그려도 소리만 들으면 괜찮아요.」 무엇이 잘못되었나요?',ARRAY['K1-2-u3-X04']::text[],false,'{"seq":3,"concept":"K1-2-u3-C2","difficulty":3,"kind":"error","stem":"「친구가 발표할 때 그림을 그려도 소리만 들으면 괜찮아요.」 무엇이 잘못되었나요?","options":[{"t":"딴짓을 하면 말하는 사람의 말을 알아듣지 못할 수 있어요","correct":true,"mis_target":"K1-2-u3-X04"},{"t":"맞는 말이에요","mis":"K1-2-u3-X04"},{"t":"그림을 그리면 더 잘 들려요","mis":"K1-2-u3-X04"}],"explanation":["딴생각을 하며 딴짓을 하면 말을 놓쳐요.","말하는 사람을 바라보며 들어요.","지도서 142~143쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L02_challenge#4','kor',1,2,'u3','L02','g1_2_kor_u3_L02_challenge','lesson_challenge','K1-2-u3-C2',3,'error','auto','친구가 떠들자 「너 때문에 하나도 안 들리잖아!」라고 소리쳤어요. 무엇이 잘못되었나요?',ARRAY['K1-2-u3-X05','K1-2-u3-X04']::text[],false,'{"seq":4,"concept":"K1-2-u3-C2","difficulty":3,"kind":"error","stem":"친구가 떠들자 「너 때문에 하나도 안 들리잖아!」라고 소리쳤어요. 무엇이 잘못되었나요?","options":[{"t":"나무라는 말 대신 「시끄럽게 떠들면 안 돼.」처럼 알려 줘요","correct":true,"mis_target":"K1-2-u3-X05"},{"t":"잘했어요 — 크게 혼내야 해요","mis":"K1-2-u3-X05"},{"t":"같이 떠들면 돼요","mis":"K1-2-u3-X04"}],"explanation":["조언하는 말은 친절하게 해요.","나무라면 친구가 속상해요.","87쪽 (3)의 말을 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L02_challenge#5','kor',1,2,'u3','L02','g1_2_kor_u3_L02_challenge','lesson_challenge','K1-2-u3-C1',3,'error','auto','발표할 때 허리를 굽히고 칠판만 보며 말했어요. 무엇이 잘못되었나요?',ARRAY['K1-2-u3-X02','K1-2-u3-X01']::text[],false,'{"seq":5,"concept":"K1-2-u3-C1","difficulty":3,"kind":"error","stem":"발표할 때 허리를 굽히고 칠판만 보며 말했어요. 무엇이 잘못되었나요?","options":[{"t":"허리를 펴고 듣는 사람을 바라보며 말해야 해요","correct":true,"mis_target":"K1-2-u3-X02"},{"t":"목소리만 더 크게 하면 돼요","mis":"K1-2-u3-X01"},{"t":"잘 발표했어요","mis":"K1-2-u3-X02"}],"explanation":["허리를 펴고 바르게 서요.","듣는 사람을 바라봐야 듣는 사람이 집중해요.","85쪽 2번이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L02_challenge#6','kor',1,2,'u3','L02','g1_2_kor_u3_L02_challenge','lesson_challenge','K1-2-u3-C1',3,'mc','auto','지도서 141쪽 — 발표를 할 때 가장 먼저 할 일은?',ARRAY['K1-2-u3-X03']::text[],false,'{"seq":6,"concept":"K1-2-u3-C1","difficulty":3,"kind":"mc","stem":"지도서 141쪽 — 발표를 할 때 가장 먼저 할 일은?","options":[{"t":"질문을 곰곰이 생각해 보고 대답할 내용을 미리 정리해요","correct":true},{"t":"생각 없이 바로 일어나요","mis":"K1-2-u3-X03"},{"t":"옆 친구에게 대신 말해 달라고 해요","mis":"K1-2-u3-X03"}],"explanation":["생각을 정리했다면 손을 가볍게 들고 듣는 사람을 바라봐요.","준비 없이 일어나면 말이 막혀요.","지도서 참고 자료예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L02_challenge#7','kor',1,2,'u3','L02','g1_2_kor_u3_L02_challenge','lesson_challenge','K1-2-u3-C2',3,'match','auto','지도서 142쪽 — 바르게 듣기 위해 필요한 몸과 하는 일을 이어 보세요.','{}'::text[],false,'{"seq":7,"concept":"K1-2-u3-C2","difficulty":3,"kind":"match","stem":"지도서 142쪽 — 바르게 듣기 위해 필요한 몸과 하는 일을 이어 보세요.","pairs":[{"l":"눈","r":"말하는 사람을 바라본다."},{"l":"귀","r":"귀 기울여 듣는다."},{"l":"허리","r":"바르게 펴고 앉는다."}],"mis":"K1-2-u3-X04","explanation":["눈으로 바라보고 귀로 기울여 들어요.","허리를 펴고 바르게 앉아요.","듣기 놀이를 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L02_challenge#8','kor',1,2,'u3','L02','g1_2_kor_u3_L02_challenge','lesson_challenge','K1-2-u3-C1',4,'sa','auto','『국어』 85쪽 — 남자아이가 탐험해 보고 싶은 곳은 어디인가요?','{}'::text[],false,'{"seq":8,"concept":"K1-2-u3-C1","difficulty":4,"kind":"sa","stem":"『국어』 85쪽 — 남자아이가 탐험해 보고 싶은 곳은 어디인가요?","answer":["북극"],"explanation":["「탐험가가 되어 북극을 탐험해 보고 싶습니다.」라고 했어요.","바르게 서서 또박또박 말해 잘 들렸어요.","발표한 말을 읽어 봐요."],"asset":{"type":"speech","turns":[{"who":"남자아이","text":"제 꿈은 탐험가입니다."},{"who":"친구(생각)","text":"알맞은 크기의 목소리로 또박또박 이야기하네."},{"who":"남자아이","text":"탐험가가 되어 북극을 탐험해 보고 싶습니다."},{"who":"친구(생각)","text":"듣는 사람을 바라보며 말하네."},{"who":"친구(생각)","text":"허리를 펴고 바른 자세로 서서 발표하네."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L02_challenge#9','kor',1,2,'u3','L02','g1_2_kor_u3_L02_challenge','lesson_challenge','K1-2-u3-C1',4,'essay','teacher','바른 자세로 발표하는 방법을 두 가지 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K1-2-u3-C1","difficulty":4,"kind":"essay","stem":"바른 자세로 발표하는 방법을 두 가지 쓰세요.","answer_guide":{"answer":"예: 허리를 펴고 바른 자세로 서서 말한다. / 알맞은 크기의 목소리로 또박또박 말한다. / 듣는 사람을 바라보며 말한다. — 두 가지를 쓰면 맞아요.","scoring_points":["발표하는 방법을 두 가지 썼는가","85쪽 2번 내용과 맞는가","문장이 자연스러운가"]},"explanation":["허리 펴기, 알맞은 목소리, 듣는 사람 바라보기가 있어요.","말끝을 흐리지 않는 것도 좋아요.","85쪽 2번이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L02_challenge#10','kor',1,2,'u3','L02','g1_2_kor_u3_L02_challenge','lesson_challenge','K1-2-u3-C2',4,'essay','teacher','『국어』 87쪽 — 다른 곳을 보며 듣는 친구에게 해 주고 싶은 말을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K1-2-u3-C2","difficulty":4,"kind":"essay","stem":"『국어』 87쪽 — 다른 곳을 보며 듣는 친구에게 해 주고 싶은 말을 쓰세요.","answer_guide":{"answer":"예: 말하는 사람을 바라보며 들어야 해. — 바른 듣기 자세를 친절하게 알려 주면 맞아요.","scoring_points":["바른 듣기 자세를 알려 주었는가","나무라지 않고 친절하게 말했는가","문장이 자연스러운가"]},"explanation":["말하는 사람을 바라보며 들어야 해요.","친절하게 알려 줘요.","87쪽 (3)이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L04_basic#1','kor',1,2,'u3','L04','g1_2_kor_u3_L04_basic','lesson_basic','K1-2-u3-C3',1,'mc','auto','『국어』 88쪽 — 기지개를 켜는 아이 그림(㉮)에 어울리는 문장은?',ARRAY['K1-2-u3-X07']::text[],false,'{"seq":1,"concept":"K1-2-u3-C3","difficulty":1,"kind":"mc","stem":"『국어』 88쪽 — 기지개를 켜는 아이 그림(㉮)에 어울리는 문장은?","options":[{"t":"일곱 시에 일어났다.","correct":true},{"t":"된장찌개를 먹었다.","mis":"K1-2-u3-X07"},{"t":"친구를 만났다.","mis":"K1-2-u3-X07"}],"explanation":["시계가 일곱 시이고 아이가 기지개를 켜요.","된장찌개는 ㉯, 친구는 ㉰ 그림이에요.","88쪽 그림이에요."],"asset":{"type":"scene","icon":"⏰🥱","text":"기지개 켜는 아이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L04_basic#2','kor',1,2,'u3','L04','g1_2_kor_u3_L04_basic','lesson_basic','K1-2-u3-C3',1,'mc','auto','『국어』 88쪽 — 밥상 앞의 아이 그림(㉯)에 어울리는 문장은?',ARRAY['K1-2-u3-X07']::text[],false,'{"seq":2,"concept":"K1-2-u3-C3","difficulty":1,"kind":"mc","stem":"『국어』 88쪽 — 밥상 앞의 아이 그림(㉯)에 어울리는 문장은?","options":[{"t":"된장찌개를 먹었다.","correct":true},{"t":"일곱 시에 일어났다.","mis":"K1-2-u3-X07"},{"t":"친구를 만났다.","mis":"K1-2-u3-X07"}],"explanation":["아이가 된장찌개를 먹고 있어요.","다른 그림의 문장과 헷갈리지 않아요.","88쪽 그림이에요."],"asset":{"type":"scene","icon":"🍲😋","text":"밥상 앞의 아이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L04_basic#3','kor',1,2,'u3','L04','g1_2_kor_u3_L04_basic','lesson_basic','K1-2-u3-C3',1,'mc','auto','『국어』 88쪽 — 손을 흔드는 두 아이 그림(㉰)에 어울리는 문장은?',ARRAY['K1-2-u3-X07']::text[],false,'{"seq":3,"concept":"K1-2-u3-C3","difficulty":1,"kind":"mc","stem":"『국어』 88쪽 — 손을 흔드는 두 아이 그림(㉰)에 어울리는 문장은?","options":[{"t":"친구를 만났다.","correct":true},{"t":"된장찌개를 먹었다.","mis":"K1-2-u3-X07"},{"t":"일곱 시에 일어났다.","mis":"K1-2-u3-X07"}],"explanation":["학교 가는 길에 친구를 만났어요.","다른 그림의 문장과 헷갈리지 않아요.","88쪽 그림이에요."],"asset":{"type":"scene","icon":"👋🧒👧","text":"손을 흔드는 두 아이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L04_basic#4','kor',1,2,'u3','L04','g1_2_kor_u3_L04_basic','lesson_basic','K1-2-u3-C3',1,'mc','auto','『국어』 89쪽 — 발표할 내용을 정리할 때 생각할 물음이 아닌 것은?',ARRAY['K1-2-u3-X07']::text[],false,'{"seq":4,"concept":"K1-2-u3-C3","difficulty":1,"kind":"mc","stem":"『국어』 89쪽 — 발표할 내용을 정리할 때 생각할 물음이 아닌 것은?","options":[{"t":"친구 옷은 무슨 색이었지?","correct":true},{"t":"무슨 일이 있었지?","mis":"K1-2-u3-X07"},{"t":"그래서 어떻게 되었지?","mis":"K1-2-u3-X07"}],"explanation":["무슨 일이·어디에서·그래서 어떻게 되었는지 생각해요.","친구 옷 색은 내가 경험한 일과 상관없어요.","89쪽 세 물음이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L04_basic#5','kor',1,2,'u3','L04','g1_2_kor_u3_L04_basic','lesson_basic','K1-2-u3-C3',2,'blank','auto','지도서 144쪽 — 빈칸에 알맞은 말은?
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L04_basic#6','kor',1,2,'u3','L04','g1_2_kor_u3_L04_basic','lesson_basic','K1-2-u3-C3',2,'match','auto','지도서 145쪽 — 물음과 대답을 이어 보세요.','{}'::text[],false,'{"seq":6,"concept":"K1-2-u3-C3","difficulty":2,"kind":"match","stem":"지도서 145쪽 — 물음과 대답을 이어 보세요.","pairs":[{"l":"누가","r":"나는"},{"l":"어디에서","r":"부엌에서"},{"l":"무엇을","r":"된장찌개를"},{"l":"어떻게","r":"맛있게 먹었다."}],"mis":"K1-2-u3-X07","explanation":["나는 부엌에서 된장찌개를 맛있게 먹었다.","물음에 답하면 한 문장이 돼요.","표의 왼쪽 물음을 차례로 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L04_basic#7','kor',1,2,'u3','L04','g1_2_kor_u3_L04_basic','lesson_basic','K1-2-u3-C1',2,'mc','auto','『국어』 90쪽 — 발표할 때의 바른 자세는?',ARRAY['K1-2-u3-X02']::text[],false,'{"seq":7,"concept":"K1-2-u3-C1","difficulty":2,"kind":"mc","stem":"『국어』 90쪽 — 발표할 때의 바른 자세는?","options":[{"t":"바른 자세로 서서 듣는 사람을 바라보며 말해요","correct":true},{"t":"고개를 숙이고 바닥을 보며 말해요","mis":"K1-2-u3-X02"},{"t":"왔다 갔다 걸어 다니며 말해요","mis":"K1-2-u3-X02"}],"explanation":["바른 자세로 서서 듣는 사람을 바라봐요.","바닥을 보거나 돌아다니면 집중하기 어려워요.","90쪽 도움말이에요."],"asset":{"type":"speech","turns":[{"who":"발표하는 친구","text":"비가 와서 가방이 흠뻑 젖었습니다."},{"who":"도움말","text":"발표할 때에는 바른 자세로 서서 듣는 사람을 바라보며 말해요."},{"who":"도움말","text":"발표를 들을 때에는 말하는 사람을 바라보며 귀 기울여 들어요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L04_basic#8','kor',1,2,'u3','L04','g1_2_kor_u3_L04_basic','lesson_basic','K1-2-u3-C2',2,'mc','auto','『국어』 90쪽 — 발표를 들을 때의 바른 자세는?',ARRAY['K1-2-u3-X04']::text[],false,'{"seq":8,"concept":"K1-2-u3-C2","difficulty":2,"kind":"mc","stem":"『국어』 90쪽 — 발표를 들을 때의 바른 자세는?","options":[{"t":"말하는 사람을 바라보며 귀 기울여 들어요","correct":true},{"t":"다른 책을 읽으며 들어요","mis":"K1-2-u3-X04"},{"t":"짝과 이야기하며 들어요","mis":"K1-2-u3-X04"}],"explanation":["말하는 사람을 바라보며 귀 기울여 들어요.","친구가 발표한 문장을 골라 쓰는 활동도 있어요.","90쪽 도움말이에요."],"asset":{"type":"speech","turns":[{"who":"발표하는 친구","text":"비가 와서 가방이 흠뻑 젖었습니다."},{"who":"도움말","text":"발표할 때에는 바른 자세로 서서 듣는 사람을 바라보며 말해요."},{"who":"도움말","text":"발표를 들을 때에는 말하는 사람을 바라보며 귀 기울여 들어요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L04_basic#9','kor',1,2,'u3','L04','g1_2_kor_u3_L04_basic','lesson_basic','K1-2-u3-C3',2,'ox','auto','아침에 먹은 음식처럼 작은 일도 발표할 거리가 돼요.',ARRAY['K1-2-u3-X06']::text[],false,'{"seq":9,"concept":"K1-2-u3-C3","difficulty":2,"kind":"ox","stem":"아침에 먹은 음식처럼 작은 일도 발표할 거리가 돼요.","answer":"O","reason_options":[{"t":"「나는 ○○을/를 먹었다.」처럼 있었던 일을 문장으로 말할 수 있으니까","correct":true},{"t":"특별한 일만 발표할 수 있으니까","mis":"K1-2-u3-X06"}],"mis":"K1-2-u3-X06","explanation":["있었던 일을 단순히 말해 보는 것도 떠올리기의 기본이에요.","사소한 일도 괜찮아요.","지도서 145쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L04_basic#10','kor',1,2,'u3','L04','g1_2_kor_u3_L04_basic','lesson_basic','K1-2-u3-C3',3,'mc','auto','「비가 와서 가방이 흠뻑 젖었습니다.」에서 「그래서 어떻게 되었지?」에 대한 대답은?',ARRAY['K1-2-u3-X07']::text[],false,'{"seq":10,"concept":"K1-2-u3-C3","difficulty":3,"kind":"mc","stem":"「비가 와서 가방이 흠뻑 젖었습니다.」에서 「그래서 어떻게 되었지?」에 대한 대답은?","options":[{"t":"가방이 흠뻑 젖었습니다","correct":true},{"t":"비가 와서","mis":"K1-2-u3-X07"},{"t":"발표를 했습니다","mis":"K1-2-u3-X07"}],"explanation":["비가 온 것은 무슨 일, 가방이 젖은 것은 어떻게 되었는지예요.","물음과 대답을 짝지어 봐요.","90쪽 친구의 발표예요."],"asset":{"type":"speech","turns":[{"who":"발표하는 친구","text":"비가 와서 가방이 흠뻑 젖었습니다."},{"who":"도움말","text":"발표할 때에는 바른 자세로 서서 듣는 사람을 바라보며 말해요."},{"who":"도움말","text":"발표를 들을 때에는 말하는 사람을 바라보며 귀 기울여 들어요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L04_challenge#1','kor',1,2,'u3','L04','g1_2_kor_u3_L04_challenge','lesson_challenge','K1-2-u3-C3',2,'mc','auto','『국어』 89쪽 — 「어디에서 있었던 일이지?」에 알맞은 대답은?',ARRAY['K1-2-u3-X07']::text[],false,'{"seq":1,"concept":"K1-2-u3-C3","difficulty":2,"kind":"mc","stem":"『국어』 89쪽 — 「어디에서 있었던 일이지?」에 알맞은 대답은?","options":[{"t":"학교 가는 길에서","correct":true},{"t":"친구를 만났다","mis":"K1-2-u3-X07"},{"t":"반가웠다","mis":"K1-2-u3-X07"}],"explanation":["어디에서는 곳을 말해요.","친구를 만난 것은 무슨 일, 반가운 것은 느낌이에요.","89쪽 세 물음이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L04_challenge#2','kor',1,2,'u3','L04','g1_2_kor_u3_L04_challenge','lesson_challenge','K1-2-u3-C1',2,'mc','auto','『국어』 90쪽 (2) — 내가 잘 발표했는지 확인하는 물음이 아닌 것은?',ARRAY['K1-2-u3-X08']::text[],false,'{"seq":2,"concept":"K1-2-u3-C1","difficulty":2,"kind":"mc","stem":"『국어』 90쪽 (2) — 내가 잘 발표했는지 확인하는 물음이 아닌 것은?","options":[{"t":"누가 제일 잘했나요?","correct":true},{"t":"알맞은 크기의 목소리로 말했나요?","mis":"K1-2-u3-X08"},{"t":"듣는 사람을 바라보며 말했나요?","mis":"K1-2-u3-X08"}],"explanation":["내 발표를 스스로 확인하는 물음이에요.","누가 제일 잘했는지 가리는 것이 아니에요.","90쪽 (2)예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L04_challenge#3','kor',1,2,'u3','L04','g1_2_kor_u3_L04_challenge','lesson_challenge','K1-2-u3-C3',3,'error','auto','친구가 「재미있었다.」 한마디만 발표했어요. 무엇이 잘못되었나요?',ARRAY['K1-2-u3-X07','K1-2-u3-X01']::text[],false,'{"seq":3,"concept":"K1-2-u3-C3","difficulty":3,"kind":"error","stem":"친구가 「재미있었다.」 한마디만 발표했어요. 무엇이 잘못되었나요?","options":[{"t":"무슨 일이 어디에서 있었는지가 빠졌어요","correct":true,"mis_target":"K1-2-u3-X07"},{"t":"잘했어요 — 짧을수록 좋아요","mis":"K1-2-u3-X07"},{"t":"더 크게 소리 지르면 돼요","mis":"K1-2-u3-X01"}],"explanation":["무슨 일이·어디에서·어떻게 되었는지 말해야 해요.","느낌만 말하면 무슨 일인지 몰라요.","89쪽 물음을 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L04_challenge#4','kor',1,2,'u3','L04','g1_2_kor_u3_L04_challenge','lesson_challenge','K1-2-u3-C3',3,'error','auto','「아침에 특별한 일이 없어서 발표할 게 없어요.」 무엇이 잘못되었나요?',ARRAY['K1-2-u3-X06']::text[],false,'{"seq":4,"concept":"K1-2-u3-C3","difficulty":3,"kind":"error","stem":"「아침에 특별한 일이 없어서 발표할 게 없어요.」 무엇이 잘못되었나요?","options":[{"t":"아침에 먹은 음식처럼 작은 일도 발표할 수 있어요","correct":true,"mis_target":"K1-2-u3-X06"},{"t":"맞아요 — 발표하지 않아도 돼요","mis":"K1-2-u3-X06"},{"t":"친구 이야기를 그대로 따라 하면 돼요","mis":"K1-2-u3-X06"}],"explanation":["「나는 ○○을/를 먹었다.」처럼 말할 수 있어요.","작은 일도 경험이에요.","지도서 144쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L04_challenge#5','kor',1,2,'u3','L04','g1_2_kor_u3_L04_challenge','lesson_challenge','K1-2-u3-C3',3,'mc','auto','지도서 147쪽 — 아침에 있었던 일을 찾지 못했을 때 할 수 있는 것은?',ARRAY['K1-2-u3-X06']::text[],false,'{"seq":5,"concept":"K1-2-u3-C3","difficulty":3,"kind":"mc","stem":"지도서 147쪽 — 아침에 있었던 일을 찾지 못했을 때 할 수 있는 것은?","options":[{"t":"「나는 내일 ○○에 가고 싶다.」처럼 내일 하고 싶은 일을 말해요","correct":true},{"t":"발표를 하지 않아요","mis":"K1-2-u3-X06"},{"t":"친구 이야기를 그대로 따라 해요","mis":"K1-2-u3-X06"}],"explanation":["내일 하고 싶은 일을 말하면 말할 거리를 찾기도 해요.","문장 틀을 쓰면 정확하게 말할 수 있어요.","대안 활동이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L04_challenge#6','kor',1,2,'u3','L04','g1_2_kor_u3_L04_challenge','lesson_challenge','K1-2-u3-C1',3,'mc','auto','『국어』 91쪽 — 바른 자세로 발표한 친구를 칭찬할 점이 아닌 것은?',ARRAY['K1-2-u3-X08']::text[],false,'{"seq":6,"concept":"K1-2-u3-C1","difficulty":3,"kind":"mc","stem":"『국어』 91쪽 — 바른 자세로 발표한 친구를 칭찬할 점이 아닌 것은?","options":[{"t":"말끝을 흐리며 작게 말했다.","correct":true},{"t":"허리를 펴고 바른 자세로 서서 말했다.","mis":"K1-2-u3-X08"},{"t":"듣는 사람을 바라보며 말했다.","mis":"K1-2-u3-X08"}],"explanation":["알맞은 목소리·바른 자세·바라보기·자세한 정리를 칭찬해요.","말끝을 흐리는 것은 칭찬할 점이 아니에요.","91쪽 표예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L04_challenge#7','kor',1,2,'u3','L04','g1_2_kor_u3_L04_challenge','lesson_challenge','K1-2-u3-C3',3,'match','auto','지도서 145쪽 글을 읽고 물음과 대답을 이어 보세요.','{}'::text[],false,'{"seq":7,"concept":"K1-2-u3-C3","difficulty":3,"kind":"match","stem":"지도서 145쪽 글을 읽고 물음과 대답을 이어 보세요.","pairs":[{"l":"언제","r":"지난여름에"},{"l":"누구와","r":"삼촌하고"},{"l":"어디에서","r":"할머니 댁 근처 개울가에서"},{"l":"느낌","r":"신나고 재미있었다."}],"mis":"K1-2-u3-X07","explanation":["언제·누구와·어디에서를 찾아요.","신나고 재미있었다는 느낌이에요.","글을 다시 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L04_challenge#8','kor',1,2,'u3','L04','g1_2_kor_u3_L04_challenge','lesson_challenge','K1-2-u3-C3',4,'sa','auto','『국어』 90쪽 — 「비가 와서 ◯◯이 흠뻑 젖었습니다.」 무엇이 젖었나요?','{}'::text[],false,'{"seq":8,"concept":"K1-2-u3-C3","difficulty":4,"kind":"sa","stem":"『국어』 90쪽 — 「비가 와서 ◯◯이 흠뻑 젖었습니다.」 무엇이 젖었나요?","answer":["가방","가방이"],"explanation":["비가 와서 가방이 흠뻑 젖었어요.","무슨 일과 어떻게 되었는지가 드러난 발표예요.","친구의 발표를 읽어 봐요."],"asset":{"type":"speech","turns":[{"who":"발표하는 친구","text":"비가 와서 가방이 흠뻑 젖었습니다."},{"who":"도움말","text":"발표할 때에는 바른 자세로 서서 듣는 사람을 바라보며 말해요."},{"who":"도움말","text":"발표를 들을 때에는 말하는 사람을 바라보며 귀 기울여 들어요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L04_challenge#9','kor',1,2,'u3','L04','g1_2_kor_u3_L04_challenge','lesson_challenge','K1-2-u3-C3',4,'essay','teacher','오늘 아침에 있었던 일을 무슨 일·어디에서·어떻게 되었는지가 드러나게 한 문장으로 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K1-2-u3-C3","difficulty":4,"kind":"essay","stem":"오늘 아침에 있었던 일을 무슨 일·어디에서·어떻게 되었는지가 드러나게 한 문장으로 쓰세요.","answer_guide":{"answer":"예: 학교 오는 길에 친구를 만나서 함께 걸어왔다. — 무슨 일과 어디에서가 드러나면 맞아요.","scoring_points":["무슨 일인지 드러나는가","어디에서·어떻게 되었는지가 있는가","한 문장으로 끝까지 썼는가"]},"explanation":["89쪽 세 물음에 답하며 써요.","작은 일도 좋아요.","한 문장으로 정리해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L04_challenge#10','kor',1,2,'u3','L04','g1_2_kor_u3_L04_challenge','lesson_challenge','K1-2-u3-C1',4,'essay','teacher','『국어』 91쪽 — 발표를 잘한 친구를 칭찬하는 말을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K1-2-u3-C1","difficulty":4,"kind":"essay","stem":"『국어』 91쪽 — 발표를 잘한 친구를 칭찬하는 말을 쓰세요.","answer_guide":{"answer":"예: ○○는 허리를 펴고 듣는 사람을 바라보며 또박또박 말했어. — 칭찬할 점이 드러나면 맞아요.","scoring_points":["칭찬할 점이 드러나는가","바른 발표 자세와 관련 있는가","문장이 자연스러운가"]},"explanation":["91쪽 표의 칭찬할 점을 떠올려요.","무엇을 잘했는지 짚어 말해요.","친구 이름을 넣어도 좋아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L06_basic#1','kor',1,2,'u3','L06','g1_2_kor_u3_L06_basic','lesson_basic','K1-2-u3-C4',1,'mc','auto','『국어』 92쪽 — 「입학을 축하합니다」가 걸린 그림은 어떤 일일까요?',ARRAY['K1-2-u3-X13']::text[],false,'{"seq":1,"concept":"K1-2-u3-C4","difficulty":1,"kind":"mc","stem":"『국어』 92쪽 — 「입학을 축하합니다」가 걸린 그림은 어떤 일일까요?","options":[{"t":"입학식","correct":true},{"t":"체육 대회","mis":"K1-2-u3-X13"},{"t":"현장 체험 학습","mis":"K1-2-u3-X13"}],"explanation":["1학년이 되어 처음 함께 한 입학식이에요.","체육 대회와 현장 체험 학습은 다른 그림이에요.","92쪽 그림이에요."],"asset":{"type":"scene","icon":"🎉🏫","text":"입학을 축하합니다"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L06_basic#2','kor',1,2,'u3','L06','g1_2_kor_u3_L06_basic','lesson_basic','K1-2-u3-C4',1,'mc','auto','『국어』 93쪽 — 「치즈 농장에 간 일」은 어느 칸에 정리했나요?',ARRAY['K1-2-u3-X09']::text[],false,'{"seq":2,"concept":"K1-2-u3-C4","difficulty":1,"kind":"mc","stem":"『국어』 93쪽 — 「치즈 농장에 간 일」은 어느 칸에 정리했나요?","options":[{"t":"재미있었던 일","correct":true},{"t":"슬펐던 일","mis":"K1-2-u3-X09"},{"t":"놀랐던 일","mis":"K1-2-u3-X09"}],"explanation":["93쪽 예시에서 재미있었던 일 칸에 썼어요.","어떤 느낌이 들었는지에 따라 칸을 나눠요.","93쪽 2번이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L06_basic#3','kor',1,2,'u3','L06','g1_2_kor_u3_L06_basic','lesson_basic','K1-2-u3-C4',1,'mc','auto','「민지가 전학을 갔어.」는 어떤 느낌의 일일까요?',ARRAY['K1-2-u3-X09']::text[],false,'{"seq":3,"concept":"K1-2-u3-C4","difficulty":1,"kind":"mc","stem":"「민지가 전학을 갔어.」는 어떤 느낌의 일일까요?","options":[{"t":"슬펐던 일","correct":true},{"t":"재미있었던 일","mis":"K1-2-u3-X09"},{"t":"신나는 일","mis":"K1-2-u3-X09"}],"explanation":["친구가 전학을 가면 슬퍼요.","재미있거나 신나는 일이 아니에요.","그때의 마음을 떠올려요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"우리는 농장에 가서 치즈를 만들었어."},{"who":"친구 2","text":"민지가 전학을 갔어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L06_basic#4','kor',1,2,'u3','L06','g1_2_kor_u3_L06_basic','lesson_basic','K1-2-u3-C4',1,'mc','auto','『국어』 94쪽 — 우리 반에서 있었던 일을 문장으로 말한 것은?',ARRAY['K1-2-u3-X07']::text[],false,'{"seq":4,"concept":"K1-2-u3-C4","difficulty":1,"kind":"mc","stem":"『국어』 94쪽 — 우리 반에서 있었던 일을 문장으로 말한 것은?","options":[{"t":"우리는 농장에 가서 치즈를 만들었어.","correct":true},{"t":"치즈.","mis":"K1-2-u3-X07"},{"t":"농장에.","mis":"K1-2-u3-X07"}],"explanation":["어디에서 무엇을 했는지 끝까지 말했어요.","낱말 하나만 말하면 문장이 아니에요.","94쪽 친구의 말이에요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"우리는 농장에 가서 치즈를 만들었어."},{"who":"친구 2","text":"민지가 전학을 갔어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L06_basic#5','kor',1,2,'u3','L06','g1_2_kor_u3_L06_basic','lesson_basic','K1-2-u3-C4',2,'match','auto','우리 반에서 있었던 일과 그때의 느낌을 이어 보세요.','{}'::text[],false,'{"seq":5,"concept":"K1-2-u3-C4","difficulty":2,"kind":"match","stem":"우리 반에서 있었던 일과 그때의 느낌을 이어 보세요.","pairs":[{"l":"치즈 농장에 가서 치즈를 만든 일","r":"재미있었던 일"},{"l":"친구 민지가 전학을 간 일","r":"슬펐던 일"},{"l":"운동회에서 박이 갑자기 펑 터진 일","r":"놀랐던 일"}],"mis":"K1-2-u3-X09","explanation":["치즈 만들기는 재미있고, 전학은 슬퍼요.","박이 갑자기 터지면 놀라요.","그때의 마음을 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
