INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L06_basic#7','kor',1,2,'u3','L06','g1_2_kor_u3_L06_basic','lesson_basic','K1-2-u3-C4',2,'mc','auto','『국어』 93쪽 — 우리 반에서 있었던 여러 가지 일을 정리하는 방법은?',ARRAY['K1-2-u3-X06','K1-2-u3-X13']::text[],false,'{"seq":7,"concept":"K1-2-u3-C4","difficulty":2,"kind":"mc","stem":"『국어』 93쪽 — 우리 반에서 있었던 여러 가지 일을 정리하는 방법은?","options":[{"t":"시간의 차례로 돌아보고 어떤 느낌이 들었는지 생각해요","correct":true},{"t":"가장 짧은 일만 골라요","mis":"K1-2-u3-X06"},{"t":"친구가 쓴 것을 그대로 베껴요","mis":"K1-2-u3-X13"}],"explanation":["시간의 차례로 돌아보며 느낌을 생각해요.","기억에 남는 일은 사람마다 달라요.","93쪽 알아 두기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L06_basic#8','kor',1,2,'u3','L06','g1_2_kor_u3_L06_basic','lesson_basic','K1-2-u3-C4',2,'mc','auto','『국어』 94쪽 3번 — 기억에 남는 일을 그림으로 나타낼 때 가장 중요한 것은?',ARRAY['K1-2-u3-X10','K1-2-u3-X13']::text[],false,'{"seq":8,"concept":"K1-2-u3-C4","difficulty":2,"kind":"mc","stem":"『국어』 94쪽 3번 — 기억에 남는 일을 그림으로 나타낼 때 가장 중요한 것은?","options":[{"t":"가장 인상 깊었던 한 장면을 골라 그리기","correct":true},{"t":"색칠을 아주 예쁘게 하기","mis":"K1-2-u3-X10"},{"t":"있었던 일을 하나도 빠짐없이 다 그리기","mis":"K1-2-u3-X13"}],"explanation":["어떤 장면을 그릴지 고르는 것이 중요해요.","미술 활동이 아니라 완성도를 겨루지 않아요.","94쪽 도움말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L06_basic#9','kor',1,2,'u3','L06','g1_2_kor_u3_L06_basic','lesson_basic','K1-2-u3-C4',2,'ox','auto','기억에 남는 일은 친구들과 모두 같아야 해요.',ARRAY['K1-2-u3-X09']::text[],false,'{"seq":9,"concept":"K1-2-u3-C4","difficulty":2,"kind":"ox","stem":"기억에 남는 일은 친구들과 모두 같아야 해요.","answer":"X","reason_options":[{"t":"사람마다 기억에 남는 일은 다를 수 있으니까","correct":true},{"t":"우리 반이 함께 한 일이니 느낌도 똑같아야 하니까","mis":"K1-2-u3-X09"}],"mis":"K1-2-u3-X09","explanation":["같은 일을 해도 기억에 남는 일은 달라요.","각자 기억에 남는 일을 골라요.","지도서 148쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L06_basic#10','kor',1,2,'u3','L06','g1_2_kor_u3_L06_basic','lesson_basic','K1-2-u3-C4',3,'mc','auto','『국어』 95쪽 4번 — 그림을 소개할 때 먼저 말할 것은?',ARRAY['K1-2-u3-X10']::text[],false,'{"seq":10,"concept":"K1-2-u3-C4","difficulty":3,"kind":"mc","stem":"『국어』 95쪽 4번 — 그림을 소개할 때 먼저 말할 것은?","options":[{"t":"어떤 일을 표현한 그림인지","correct":true},{"t":"크레파스를 몇 개 썼는지","mis":"K1-2-u3-X10"},{"t":"그림을 몇 분 동안 그렸는지","mis":"K1-2-u3-X10"}],"explanation":["어떤 일인지 먼저 말하고 누가 무엇을 하는지, 그릴 때 든 생각까지 말해요.","도구나 시간은 중요하지 않아요.","지도서 150쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L06_challenge#1','kor',1,2,'u3','L06','g1_2_kor_u3_L06_challenge','lesson_challenge','K1-2-u3-C4',2,'mc','auto','언제·어디에서·무엇을 했는지가 모두 들어간 문장은?',ARRAY['K1-2-u3-X07']::text[],false,'{"seq":1,"concept":"K1-2-u3-C4","difficulty":2,"kind":"mc","stem":"언제·어디에서·무엇을 했는지가 모두 들어간 문장은?","options":[{"t":"봄에 우리는 운동장에서 체육 대회를 했어.","correct":true},{"t":"체육 대회.","mis":"K1-2-u3-X07"},{"t":"재미있었어.","mis":"K1-2-u3-X07"}],"explanation":["봄에(언제), 운동장에서(어디에서), 체육 대회를(무엇을)이 다 있어요.","낱말 하나나 느낌만으로는 부족해요.","94쪽 도움말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L06_challenge#2','kor',1,2,'u3','L06','g1_2_kor_u3_L06_challenge','lesson_challenge','K1-2-u3-C4',2,'mc','auto','지도서 150쪽 — 「물가에서 물고기를 잡았다.」를 그림으로 나타낼 때 꼭 들어갈 것은?',ARRAY['K1-2-u3-X13','K1-2-u3-X10']::text[],false,'{"seq":2,"concept":"K1-2-u3-C4","difficulty":2,"kind":"mc","stem":"지도서 150쪽 — 「물가에서 물고기를 잡았다.」를 그림으로 나타낼 때 꼭 들어갈 것은?","options":[{"t":"물가와 물고기를 잡는 모습","correct":true},{"t":"아무 장면이나","mis":"K1-2-u3-X13"},{"t":"예쁜 무늬만","mis":"K1-2-u3-X10"}],"explanation":["글과 같은 일의 장면을 그려요.","그림만 보고도 무슨 일인지 알 수 있어야 해요.","지도서 그림 예시예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L06_challenge#3','kor',1,2,'u3','L06','g1_2_kor_u3_L06_challenge','lesson_challenge','K1-2-u3-C4',3,'error','auto','「슬펐던 일」 칸에 「생일 선물을 받은 일」을 썼어요. 무엇이 잘못되었나요?',ARRAY['K1-2-u3-X09']::text[],false,'{"seq":3,"concept":"K1-2-u3-C4","difficulty":3,"kind":"error","stem":"「슬펐던 일」 칸에 「생일 선물을 받은 일」을 썼어요. 무엇이 잘못되었나요?","options":[{"t":"기쁜 일이라 「재미있었던 일」에 넣어야 해요","correct":true,"mis_target":"K1-2-u3-X09"},{"t":"잘 넣었어요","mis":"K1-2-u3-X09"},{"t":"「놀랐던 일」에만 넣을 수 있어요","mis":"K1-2-u3-X09"}],"explanation":["일과 그때의 느낌이 맞아야 해요.","선물을 받으면 기쁘고 즐거워요.","그때의 마음을 먼저 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L06_challenge#4','kor',1,2,'u3','L06','g1_2_kor_u3_L06_challenge','lesson_challenge','K1-2-u3-C4',3,'error','auto','그림 한 장에 입학식, 체육 대회, 현장 체험 학습을 모두 그렸어요. 무엇이 잘못되었나요?',ARRAY['K1-2-u3-X13','K1-2-u3-X10']::text[],false,'{"seq":4,"concept":"K1-2-u3-C4","difficulty":3,"kind":"error","stem":"그림 한 장에 입학식, 체육 대회, 현장 체험 학습을 모두 그렸어요. 무엇이 잘못되었나요?","options":[{"t":"가장 기억에 남는 한 장면만 골라 그려야 해요","correct":true,"mis_target":"K1-2-u3-X13"},{"t":"잘했어요 — 많이 그릴수록 좋아요","mis":"K1-2-u3-X13"},{"t":"색칠을 더 해야 해요","mis":"K1-2-u3-X10"}],"explanation":["있었던 일을 모두 그릴 수는 없어요.","한 장면을 골라야 무슨 일인지 잘 보여요.","94쪽 3번이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L06_challenge#5','kor',1,2,'u3','L06','g1_2_kor_u3_L06_challenge','lesson_challenge','K1-2-u3-C4',3,'error','auto','친구가 그림 색칠에만 시간을 다 써서 소개할 문장을 정하지 못했어요. 무엇이 잘못되었나요?',ARRAY['K1-2-u3-X10']::text[],false,'{"seq":5,"concept":"K1-2-u3-C4","difficulty":3,"kind":"error","stem":"친구가 그림 색칠에만 시간을 다 써서 소개할 문장을 정하지 못했어요. 무엇이 잘못되었나요?","options":[{"t":"그림은 무슨 일인지 보이면 돼요 — 문장으로 말할 것도 정해요","correct":true,"mis_target":"K1-2-u3-X10"},{"t":"잘했어요 — 그림이 제일 중요해요","mis":"K1-2-u3-X10"},{"t":"색칠을 더 꼼꼼히 해야 해요","mis":"K1-2-u3-X10"}],"explanation":["그림 그리기는 미술 활동이 아니에요.","무슨 일인지 문장으로 말하는 것이 중요해요.","지도서 150쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L06_challenge#6','kor',1,2,'u3','L06','g1_2_kor_u3_L06_challenge','lesson_challenge','K1-2-u3-C4',3,'mc','auto','지도서 148쪽 — 지난 일이 잘 떠오르지 않을 때 도움이 되는 것은?',ARRAY['K1-2-u3-X06']::text[],false,'{"seq":6,"concept":"K1-2-u3-C4","difficulty":3,"kind":"mc","stem":"지도서 148쪽 — 지난 일이 잘 떠오르지 않을 때 도움이 되는 것은?","options":[{"t":"학급 활동 사진이나 기록을 보며 떠올려요","correct":true},{"t":"떠올리기를 포기해요","mis":"K1-2-u3-X06"},{"t":"아무 일이나 지어내요","mis":"K1-2-u3-X06"}],"explanation":["사진이나 기록을 보면 경험을 더 풍부하게 떠올려요.","친구의 말을 들어도 도움이 돼요.","지도서 유의점이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L06_challenge#7','kor',1,2,'u3','L06','g1_2_kor_u3_L06_challenge','lesson_challenge','K1-2-u3-C4',3,'match','auto','지도서 150쪽 — 그림과 어울리는 문장을 이어 보세요.','{}'::text[],false,'{"seq":7,"concept":"K1-2-u3-C4","difficulty":3,"kind":"match","stem":"지도서 150쪽 — 그림과 어울리는 문장을 이어 보세요.","pairs":[{"l":"🐟 물가의 아이들","r":"물가에서 물고기를 잡았다."},{"l":"🏃 공원의 친구들","r":"공원에서 친구들과 술래잡기를 했다."},{"l":"🌇 붉은 하늘","r":"산책하다가 노을을 보았다."}],"mis":"K1-2-u3-X13","explanation":["그림은 문장과 같은 일을 담아요.","물고기·술래잡기·노을 장면이에요.","그림 예시를 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L06_challenge#8','kor',1,2,'u3','L06','g1_2_kor_u3_L06_challenge','lesson_challenge','K1-2-u3-C4',4,'sa','auto','『국어』 94쪽 — 우리는 농장에 가서 무엇을 만들었나요?','{}'::text[],false,'{"seq":8,"concept":"K1-2-u3-C4","difficulty":4,"kind":"sa","stem":"『국어』 94쪽 — 우리는 농장에 가서 무엇을 만들었나요?","answer":["치즈"],"explanation":["「우리는 농장에 가서 치즈를 만들었어.」라고 했어요.","어디에서 무엇을 했는지 드러난 문장이에요.","친구의 말을 읽어 봐요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"우리는 농장에 가서 치즈를 만들었어."},{"who":"친구 2","text":"민지가 전학을 갔어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L06_challenge#9','kor',1,2,'u3','L06','g1_2_kor_u3_L06_challenge','lesson_challenge','K1-2-u3-C4',4,'essay','teacher','『국어』 94쪽 3번 — 1학년이 되어 가장 기억에 남는 일과 그 까닭을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K1-2-u3-C4","difficulty":4,"kind":"essay","stem":"『국어』 94쪽 3번 — 1학년이 되어 가장 기억에 남는 일과 그 까닭을 쓰세요.","answer_guide":{"answer":"예: 체육 대회에서 달리기를 한 일이 기억에 남아요. 처음으로 일 등을 해서 무척 기뻤기 때문이에요. — 일과 까닭이 있으면 맞아요.","scoring_points":["기억에 남는 일을 썼는가","까닭을 썼는가","문장이 자연스러운가"]},"explanation":["가장 기억에 남는 일을 하나 골라요.","왜 기억에 남는지 까닭을 써요.","그때의 느낌을 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L06_challenge#10','kor',1,2,'u3','L06','g1_2_kor_u3_L06_challenge','lesson_challenge','K1-2-u3-C4',4,'essay','teacher','「우리는 (   )을/를 했다.」 틀에 맞추어 우리 반이 함께 한 일을 한 문장으로 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K1-2-u3-C4","difficulty":4,"kind":"essay","stem":"「우리는 (   )을/를 했다.」 틀에 맞추어 우리 반이 함께 한 일을 한 문장으로 쓰세요.","answer_guide":{"answer":"예: 우리는 강당에서 입학식을 했다. / 우리는 교실에서 덧셈 놀이를 했다. — 틀에 맞게 한 일이 들어가면 맞아요.","scoring_points":["틀에 맞게 썼는가","우리 반이 함께 한 일인가","문장이 자연스러운가"]},"explanation":["( ) 안에 한 일을 넣어요.","어디에서를 넣으면 더 자세해요.","지도서 149쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L08_basic#1','kor',1,2,'u3','L08','g1_2_kor_u3_L08_basic','lesson_basic','K1-2-u3-C5',1,'mc','auto','『국어』 96쪽 — 찬호의 그림일기 맨 위에는 무엇이 쓰여 있나요?',ARRAY['K1-2-u3-X11']::text[],false,'{"seq":1,"concept":"K1-2-u3-C5","difficulty":1,"kind":"mc","stem":"『국어』 96쪽 — 찬호의 그림일기 맨 위에는 무엇이 쓰여 있나요?","options":[{"t":"날짜와 요일, 날씨","correct":true},{"t":"그림","mis":"K1-2-u3-X11"},{"t":"생각이나 느낌","mis":"K1-2-u3-X11"}],"explanation":["맨 위에 날짜와 요일, 날씨를 써요.","그 밑에 그림과 글이 있어요.","그림일기 맨 윗줄을 봐요."],"asset":{"type":"diary","date":"20○○년 10월 24일 일요일","weather":"해가 쨍쨍한 날","picture":"🍎🌳👵🧒","lines":["과수원을 하시는 할머니 댁에 놀러 갔다.","나와 동생은 빨갛게 익은 사과를 땄다.","사과를 직접 따 보니 정말 재미있었다."],"name":"찬호"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
