INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L08_basic#9','kor',1,2,'u3','L08','g1_2_kor_u3_L08_basic','lesson_basic','K1-2-u3-C5',2,'ox','auto','『국어』 98쪽 그림일기는 잘 쓴 그림일기예요.',ARRAY['K1-2-u3-X14']::text[],false,'{"seq":9,"concept":"K1-2-u3-C5","difficulty":2,"kind":"ox","stem":"『국어』 98쪽 그림일기는 잘 쓴 그림일기예요.","answer":"X","reason_options":[{"t":"늘 하는 일을 늘어놓기만 하고 날씨와 생각이나 느낌이 없으니까","correct":true},{"t":"하루 동안 한 일을 빠짐없이 다 썼으니까","mis":"K1-2-u3-X14"}],"mis":"K1-2-u3-X14","explanation":["날씨 칸이 비어 있어요.","기억에 남는 일이 무엇인지 알 수 없어요.","98쪽 3번이에요."],"asset":{"type":"diary","date":"20○○년 10월 22일 화요일","weather":null,"picture":"🛏️😴","lines":["나는 오늘 아침에 일어나 밥을 먹고","학교에 가서 공부를 했다.","그리고 집에 와서 숙제를 하고 잤다."]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L08_basic#10','kor',1,2,'u3','L08','g1_2_kor_u3_L08_basic','lesson_basic','K1-2-u3-C5',3,'mc','auto','그림일기에 쓰기 좋은 기억에 남는 일은?',ARRAY['K1-2-u3-X14','K1-2-u3-X06']::text[],false,'{"seq":10,"concept":"K1-2-u3-C5","difficulty":3,"kind":"mc","stem":"그림일기에 쓰기 좋은 기억에 남는 일은?","options":[{"t":"처음 해 보았거나 무척 즐거웠던 일","correct":true},{"t":"날마다 똑같이 하는 일","mis":"K1-2-u3-X14"},{"t":"아무 느낌이 없었던 일","mis":"K1-2-u3-X06"}],"explanation":["새롭거나 즐거웠던 일, 특별한 느낌이 있었던 일이 좋아요.","날마다 하는 일은 기억에 남는 일이 아니에요.","지도서 155쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L08_challenge#1','kor',1,2,'u3','L08','g1_2_kor_u3_L08_challenge','lesson_challenge','K1-2-u3-C5',2,'mc','auto','『국어』 98쪽 그림일기에서 빠진 것은?',ARRAY['K1-2-u3-X11']::text[],false,'{"seq":1,"concept":"K1-2-u3-C5","difficulty":2,"kind":"mc","stem":"『국어』 98쪽 그림일기에서 빠진 것은?","options":[{"t":"날씨","correct":true},{"t":"날짜","mis":"K1-2-u3-X11"},{"t":"그림","mis":"K1-2-u3-X11"}],"explanation":["날짜와 요일은 썼지만 날씨 칸이 비어 있어요.","그림도 있어요.","맨 윗줄을 봐요."],"asset":{"type":"diary","date":"20○○년 10월 22일 화요일","weather":null,"picture":"🛏️😴","lines":["나는 오늘 아침에 일어나 밥을 먹고","학교에 가서 공부를 했다.","그리고 집에 와서 숙제를 하고 잤다."]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L08_challenge#2','kor',1,2,'u3','L08','g1_2_kor_u3_L08_challenge','lesson_challenge','K1-2-u3-C5',2,'mc','auto','찬호가 사과를 따고 난 생각이나 느낌은?',ARRAY['K1-2-u3-X15']::text[],false,'{"seq":2,"concept":"K1-2-u3-C5","difficulty":2,"kind":"mc","stem":"찬호가 사과를 따고 난 생각이나 느낌은?","options":[{"t":"정말 재미있었다","correct":true},{"t":"사과가 빨갛게 익었다","mis":"K1-2-u3-X15"},{"t":"할머니 댁에 놀러 갔다","mis":"K1-2-u3-X15"}],"explanation":["「사과를 직접 따 보니 정말 재미있었다.」라고 썼어요.","사과 색이나 놀러 간 일은 있었던 일이에요.","셋째 줄을 읽어 봐요."],"asset":{"type":"diary","date":"20○○년 10월 24일 일요일","weather":"해가 쨍쨍한 날","picture":"🍎🌳👵🧒","lines":["과수원을 하시는 할머니 댁에 놀러 갔다.","나와 동생은 빨갛게 익은 사과를 땄다.","사과를 직접 따 보니 정말 재미있었다."],"name":"찬호"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L08_challenge#3','kor',1,2,'u3','L08','g1_2_kor_u3_L08_challenge','lesson_challenge','K1-2-u3-C5',3,'error','auto','『국어』 98쪽 그림일기의 글은 무엇이 잘못되었나요?',ARRAY['K1-2-u3-X14','K1-2-u3-X11']::text[],false,'{"seq":3,"concept":"K1-2-u3-C5","difficulty":3,"kind":"error","stem":"『국어』 98쪽 그림일기의 글은 무엇이 잘못되었나요?","options":[{"t":"늘 하는 일을 늘어놓아 기억에 남는 일을 알 수 없어요 — 한 가지를 골라 자세히 써요","correct":true,"mis_target":"K1-2-u3-X14"},{"t":"그림이 없어요","mis":"K1-2-u3-X11"},{"t":"잘 썼어요","mis":"K1-2-u3-X14"}],"explanation":["일어나 밥 먹고 공부하고 잔 것은 늘 하는 일이에요.","이 일기를 나중에 보면 그날을 알기 어려워요.","98쪽 3번이에요."],"asset":{"type":"diary","date":"20○○년 10월 22일 화요일","weather":null,"picture":"🛏️😴","lines":["나는 오늘 아침에 일어나 밥을 먹고","학교에 가서 공부를 했다.","그리고 집에 와서 숙제를 하고 잤다."]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L08_challenge#4','kor',1,2,'u3','L08','g1_2_kor_u3_L08_challenge','lesson_challenge','K1-2-u3-C5',3,'error','auto','친구가 그림일기에 「준비물: 돗자리, 물」을 썼어요. 무엇이 잘못되었나요?',ARRAY['K1-2-u3-X12','K1-2-u3-X11']::text[],false,'{"seq":4,"concept":"K1-2-u3-C5","difficulty":3,"kind":"error","stem":"친구가 그림일기에 「준비물: 돗자리, 물」을 썼어요. 무엇이 잘못되었나요?","options":[{"t":"알려 주는 글에 들어갈 말이에요 — 내가 겪은 일과 느낌을 써요","correct":true,"mis_target":"K1-2-u3-X12"},{"t":"잘 썼어요","mis":"K1-2-u3-X12"},{"t":"날씨를 지워야 해요","mis":"K1-2-u3-X11"}],"explanation":["그림일기에는 내가 겪은 일을 써요.","준비물은 안내하는 글에 들어가요.","107쪽 색칠하기를 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L08_challenge#5','kor',1,2,'u3','L08','g1_2_kor_u3_L08_challenge','lesson_challenge','K1-2-u3-C5',3,'error','auto','친구가 날씨를 글의 맨 끝에 썼어요. 무엇이 잘못되었나요?',ARRAY['K1-2-u3-X11']::text[],false,'{"seq":5,"concept":"K1-2-u3-C5","difficulty":3,"kind":"error","stem":"친구가 날씨를 글의 맨 끝에 썼어요. 무엇이 잘못되었나요?","options":[{"t":"날씨는 맨 위 날짜와 요일 옆에 써요","correct":true,"mis_target":"K1-2-u3-X11"},{"t":"잘 썼어요","mis":"K1-2-u3-X11"},{"t":"날씨는 쓰지 않아도 돼요","mis":"K1-2-u3-X11"}],"explanation":["맨 윗줄에 날짜와 요일, 날씨를 써요.","자리를 지키면 읽기 쉬워요.","96쪽 찬호의 일기를 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L08_challenge#6','kor',1,2,'u3','L08','g1_2_kor_u3_L08_challenge','lesson_challenge','K1-2-u3-C5',3,'mc','auto','지도서 157쪽 — 「나는 오늘 친구와 인형 놀이를 했다. 참 재미있었다.」를 고친다면?',ARRAY['K1-2-u3-X15','K1-2-u3-X14']::text[],false,'{"seq":6,"concept":"K1-2-u3-C5","difficulty":3,"kind":"mc","stem":"지도서 157쪽 — 「나는 오늘 친구와 인형 놀이를 했다. 참 재미있었다.」를 고친다면?","options":[{"t":"어떤 놀이가 어떻게 재미있었는지 자세히 써요","correct":true},{"t":"「참 재미있었다」를 세 번 써요","mis":"K1-2-u3-X15"},{"t":"하루 일을 모두 덧붙여요","mis":"K1-2-u3-X14"}],"explanation":["「나는 오늘」, 「참 재미있었다」는 버릇처럼 쓰는 말이에요.","무엇이 어떻게 재미있었는지 써야 해요.","지도서 참고 자료예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L08_challenge#7','kor',1,2,'u3','L08','g1_2_kor_u3_L08_challenge','lesson_challenge','K1-2-u3-C5',3,'match','auto','『국어』 99쪽 4번 — 주의할 점과 보기의 말을 이어 보세요.','{}'::text[],false,'{"seq":7,"concept":"K1-2-u3-C5","difficulty":3,"kind":"match","stem":"『국어』 99쪽 4번 — 주의할 점과 보기의 말을 이어 보세요.","pairs":[{"l":"날짜와 요일, ___을/를 쓴다.","r":"날씨"},{"l":"___이/가 그림에 잘 드러나게 표현한다.","r":"경험한 일"},{"l":"경험한 일이 드러나게 ___을/를 자세히 쓴다.","r":"내용"},{"l":"경험한 일에 대한 ___을/를 쓴다.","r":"생각이나 느낌"}],"mis":"K1-2-u3-X11","explanation":["날씨·경험한 일이에요.","내용·생각이나 느낌이에요.","99쪽 보기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L08_challenge#8','kor',1,2,'u3','L08','g1_2_kor_u3_L08_challenge','lesson_challenge','K1-2-u3-C5',4,'sa','auto','『국어』 96쪽 — 찬호와 동생이 딴 과일은 무엇인가요?','{}'::text[],false,'{"seq":8,"concept":"K1-2-u3-C5","difficulty":4,"kind":"sa","stem":"『국어』 96쪽 — 찬호와 동생이 딴 과일은 무엇인가요?","answer":["사과"],"explanation":["빨갛게 익은 사과를 땄어요.","과수원을 하시는 할머니 댁이에요.","둘째 줄을 읽어 봐요."],"asset":{"type":"diary","date":"20○○년 10월 24일 일요일","weather":"해가 쨍쨍한 날","picture":"🍎🌳👵🧒","lines":["과수원을 하시는 할머니 댁에 놀러 갔다.","나와 동생은 빨갛게 익은 사과를 땄다.","사과를 직접 따 보니 정말 재미있었다."],"name":"찬호"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L08_challenge#9','kor',1,2,'u3','L08','g1_2_kor_u3_L08_challenge','lesson_challenge','K1-2-u3-C5',4,'sa','auto','그림일기 맨 윗줄에 날짜와 요일과 함께 쓰는 것은 무엇인가요?','{}'::text[],false,'{"seq":9,"concept":"K1-2-u3-C5","difficulty":4,"kind":"sa","stem":"그림일기 맨 윗줄에 날짜와 요일과 함께 쓰는 것은 무엇인가요?","answer":["날씨"],"explanation":["날짜와 요일, 날씨를 써요.","국어활동 39쪽에서도 확인했어요.","96쪽 찬호의 일기를 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L08_challenge#10','kor',1,2,'u3','L08','g1_2_kor_u3_L08_challenge','lesson_challenge','K1-2-u3-C5',4,'essay','teacher','『국어』 98쪽 그림일기를 고쳐 쓴다면 무엇을 어떻게 바꾸면 좋을지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K1-2-u3-C5","difficulty":4,"kind":"essay","stem":"『국어』 98쪽 그림일기를 고쳐 쓴다면 무엇을 어떻게 바꾸면 좋을지 쓰세요.","answer_guide":{"answer":"예: 날씨를 쓰고, 그날 기억에 남는 일 하나를 골라 누구와 무엇을 했는지와 느낌을 자세히 쓴다. — 날씨·한 가지 일·느낌 가운데 둘 이상이면 맞아요.","scoring_points":["날씨를 쓰라고 했는가","기억에 남는 일 하나를 고르라고 했는가","생각이나 느낌을 쓰라고 했는가"]},"explanation":["빠진 날씨부터 채워요.","늘 하는 일 대신 기억에 남는 일을 써요.","느낌도 꼭 써요."],"asset":{"type":"diary","date":"20○○년 10월 22일 화요일","weather":null,"picture":"🛏️😴","lines":["나는 오늘 아침에 일어나 밥을 먹고","학교에 가서 공부를 했다.","그리고 집에 와서 숙제를 하고 잤다."]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L10_basic#1','kor',1,2,'u3','L10','g1_2_kor_u3_L10_basic','lesson_basic','K1-2-u3-C6',1,'mc','auto','『국어』 100쪽 — 아침에 있었던 일로 쓰인 것은?',ARRAY['K1-2-u3-X14']::text[],false,'{"seq":1,"concept":"K1-2-u3-C6","difficulty":1,"kind":"mc","stem":"『국어』 100쪽 — 아침에 있었던 일로 쓰인 것은?","options":[{"t":"늦잠 잔 일","correct":true},{"t":"동생과 동화책을 읽은 일","mis":"K1-2-u3-X14"},{"t":"선생님께 칭찬받은 일","mis":"K1-2-u3-X14"}],"explanation":["아침 칸에 늦잠 잔 일이 있어요.","동화책은 저녁, 칭찬은 낮이에요.","100쪽 그림이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L10_basic#2','kor',1,2,'u3','L10','g1_2_kor_u3_L10_basic','lesson_basic','K1-2-u3-C6',1,'mc','auto','『국어』 100쪽 — 저녁에 있었던 일로 쓰인 것은?',ARRAY['K1-2-u3-X14']::text[],false,'{"seq":2,"concept":"K1-2-u3-C6","difficulty":1,"kind":"mc","stem":"『국어』 100쪽 — 저녁에 있었던 일로 쓰인 것은?","options":[{"t":"동생과 동화책을 읽은 일","correct":true},{"t":"늦잠 잔 일","mis":"K1-2-u3-X14"},{"t":"선생님께 칭찬받은 일","mis":"K1-2-u3-X14"}],"explanation":["저녁 칸에 동생과 동화책을 읽은 일이 있어요.","아침·낮·저녁 차례로 떠올려요.","100쪽 그림이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L10_basic#3','kor',1,2,'u3','L10','g1_2_kor_u3_L10_basic','lesson_basic','K1-2-u3-C6',1,'mc','auto','『국어』 101쪽 — 그림일기에 쓸 내용을 정리하는 물음이 아닌 것은?',ARRAY['K1-2-u3-X07','K1-2-u3-X15']::text[],false,'{"seq":3,"concept":"K1-2-u3-C6","difficulty":1,"kind":"mc","stem":"『국어』 101쪽 — 그림일기에 쓸 내용을 정리하는 물음이 아닌 것은?","options":[{"t":"어제 저녁 반찬은 몇 가지였나요?","correct":true},{"t":"누구와 있었던 일인가요?","mis":"K1-2-u3-X07"},{"t":"어떤 생각이나 느낌이 들었나요?","mis":"K1-2-u3-X15"}],"explanation":["언제·어디에서, 누구와, 무슨 일, 생각이나 느낌을 물어요.","반찬 수는 기억에 남는 일과 상관없어요.","101쪽 네 물음이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L10_basic#4','kor',1,2,'u3','L10','g1_2_kor_u3_L10_basic','lesson_basic','K1-2-u3-C6',1,'mc','auto','지도서 160쪽 — 날씨를 재미있게 나타낸 것은?',ARRAY['K1-2-u3-X11']::text[],false,'{"seq":4,"concept":"K1-2-u3-C6","difficulty":1,"kind":"mc","stem":"지도서 160쪽 — 날씨를 재미있게 나타낸 것은?","options":[{"t":"해님이 방긋","correct":true},{"t":"일요일","mis":"K1-2-u3-X11"},{"t":"김밥","mis":"K1-2-u3-X11"}],"explanation":["날씨를 「해님이 방긋」처럼 재미있게 나타낼 수 있어요.","일요일은 요일이고 김밥은 음식이에요.","날씨 칸에 쓰는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L10_basic#5','kor',1,2,'u3','L10','g1_2_kor_u3_L10_basic','lesson_basic','K1-2-u3-C6',2,'match','auto','지도서 159쪽 — 물음과 대답을 이어 보세요.','{}'::text[],false,'{"seq":5,"concept":"K1-2-u3-C6","difficulty":2,"kind":"match","stem":"지도서 159쪽 — 물음과 대답을 이어 보세요.","pairs":[{"l":"언제?","r":"운동회 날"},{"l":"무슨 일이?","r":"박이 터질 때까지 콩 주머니를 던졌다."},{"l":"어떤 느낌?","r":"우리 편이 이겨서 기분이 좋았다."}],"mis":"K1-2-u3-X07","explanation":["운동회 날, 콩 주머니 던지기, 기분이 좋았다예요.","물음에 답하면 일기 내용이 정리돼요.","교사 질문과 학생 대답이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L10_basic#6','kor',1,2,'u3','L10','g1_2_kor_u3_L10_basic','lesson_basic','K1-2-u3-C6',2,'mc','auto','지도서 158쪽 — 이 일기를 읽고 더 알고 싶은 것은?',ARRAY['K1-2-u3-X14']::text[],false,'{"seq":6,"concept":"K1-2-u3-C6","difficulty":2,"kind":"mc","stem":"지도서 158쪽 — 이 일기를 읽고 더 알고 싶은 것은?","options":[{"t":"장미 공원에서 무엇을 했고 어떤 느낌이 들었는지","correct":true},{"t":"김밥이 몇 줄이었는지","mis":"K1-2-u3-X14"},{"t":"걸어간 길의 길이","mis":"K1-2-u3-X14"}],"explanation":["있었던 일이 자세하지 않아 궁금한 점이 생겨요.","일기는 경험한 일을 자세하게 써야 해요.","예시 일기를 읽어 봐요."],"asset":{"type":"passage","lines":["오늘은 즐거운 현장 체험 학습 날이다.","어머니께서 맛있는 김밥을 싸 주셨다.","선생님을 따라서 장미 공원으로 걸어갔다.","공원에는 예쁜 장미가 활짝 피어 있었다."],"title":"현장 체험 학습"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L10_basic#7','kor',1,2,'u3','L10','g1_2_kor_u3_L10_basic','lesson_basic','K1-2-u3-C6',2,'mc','auto','지도서 159쪽 — 그림일기의 그림을 그릴 때 주의할 점은?',ARRAY['K1-2-u3-X16','K1-2-u3-X10']::text[],false,'{"seq":7,"concept":"K1-2-u3-C6","difficulty":2,"kind":"mc","stem":"지도서 159쪽 — 그림일기의 그림을 그릴 때 주의할 점은?","options":[{"t":"너무 오래 그리지 않고 글 쓸 시간을 남겨요","correct":true},{"t":"글은 빼고 그림만 꼼꼼히 그려요","mis":"K1-2-u3-X16"},{"t":"색칠을 가장 오래 해요","mis":"K1-2-u3-X10"}],"explanation":["그림을 그리는 데 너무 많은 시간이 걸리지 않게 해요.","글도 그림일기의 중요한 부분이에요.","지도서 유의점이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
