INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L10_basic#9','kor',1,2,'u3','L10','g1_2_kor_u3_L10_basic','lesson_basic','K1-2-u3-C6',2,'ox','auto','그림일기에는 「나는 오늘」, 「참 재미있었다」를 꼭 써야 해요.',ARRAY['K1-2-u3-X15']::text[],false,'{"seq":9,"concept":"K1-2-u3-C6","difficulty":2,"kind":"ox","stem":"그림일기에는 「나는 오늘」, 「참 재미있었다」를 꼭 써야 해요.","answer":"X","reason_options":[{"t":"일기는 내가 그날 한 일을 쓴 글이니 버릇처럼 쓰는 말은 빼도 되니까","correct":true},{"t":"그 말이 없으면 일기가 아니니까","mis":"K1-2-u3-X15"}],"mis":"K1-2-u3-X15","explanation":["상투적인 표현은 생략해도 돼요.","대신 무엇이 어떻게 재미있었는지 써요.","지도서 155쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
