INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L10_challenge#2','kor',1,2,'u3','L10','g1_2_kor_u3_L10_challenge','lesson_challenge','K1-2-u3-C6',2,'mc','auto','지도서 157쪽 — 「공을 던지고 있는데 자꾸 끼어들었다. 매우 기분이 나빴다.」에 보완할 점은?',ARRAY['K1-2-u3-X15','K1-2-u3-X16']::text[],false,'{"seq":2,"concept":"K1-2-u3-C6","difficulty":2,"kind":"mc","stem":"지도서 157쪽 — 「공을 던지고 있는데 자꾸 끼어들었다. 매우 기분이 나빴다.」에 보완할 점은?","options":[{"t":"언제 어디에서 누가 끼어들었는지 써요","correct":true},{"t":"「참 재미있었다」를 덧붙여요","mis":"K1-2-u3-X15"},{"t":"그림을 더 크게 그려요","mis":"K1-2-u3-X16"}],"explanation":["누가 끼어들었는지 몰라 무슨 일인지 알기 어려워요.","언제·어디에서·누구와를 써요.","지도서 참고 자료예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L10_challenge#3','kor',1,2,'u3','L10','g1_2_kor_u3_L10_challenge','lesson_challenge','K1-2-u3-C6',3,'error','auto','친구가 그림만 꼼꼼히 색칠하다 글 칸을 비워 두었어요. 무엇이 잘못되었나요?',ARRAY['K1-2-u3-X16','K1-2-u3-X10','K1-2-u3-X11']::text[],false,'{"seq":3,"concept":"K1-2-u3-C6","difficulty":3,"kind":"error","stem":"친구가 그림만 꼼꼼히 색칠하다 글 칸을 비워 두었어요. 무엇이 잘못되었나요?","options":[{"t":"그림은 간단히 하고 글로 경험한 일과 느낌을 써야 해요","correct":true,"mis_target":"K1-2-u3-X16"},{"t":"잘했어요 — 그림이 더 중요해요","mis":"K1-2-u3-X10"},{"t":"날씨 칸을 지워야 해요","mis":"K1-2-u3-X11"}],"explanation":["그림일기는 글과 그림이 함께 있어야 해요.","그림에 시간을 다 쓰면 안 돼요.","지도서 159쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L10_challenge#4','kor',1,2,'u3','L10','g1_2_kor_u3_L10_challenge','lesson_challenge','K1-2-u3-C6',3,'error','auto','친구가 그림일기 글에 「좋았다.」만 썼어요. 무엇이 잘못되었나요?',ARRAY['K1-2-u3-X15','K1-2-u3-X11']::text[],false,'{"seq":4,"concept":"K1-2-u3-C6","difficulty":3,"kind":"error","stem":"친구가 그림일기 글에 「좋았다.」만 썼어요. 무엇이 잘못되었나요?","options":[{"t":"무엇을 했고 왜 좋았는지가 빠졌어요","correct":true,"mis_target":"K1-2-u3-X15"},{"t":"잘 썼어요","mis":"K1-2-u3-X15"},{"t":"날씨가 없어요","mis":"K1-2-u3-X11"}],"explanation":["경험한 일과 생각이나 느낌을 자세히 써요.","왜 좋았는지 까닭을 붙여요.","103쪽 점검이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L10_challenge#5','kor',1,2,'u3','L10','g1_2_kor_u3_L10_challenge','lesson_challenge','K1-2-u3-C6',3,'error','auto','친구가 그림일기를 다 쓰고 다시 읽지 않고 바로 냈어요. 무엇을 하면 좋을까요?',ARRAY['K1-2-u3-X17','K1-2-u3-X08']::text[],false,'{"seq":5,"concept":"K1-2-u3-C6","difficulty":3,"kind":"error","stem":"친구가 그림일기를 다 쓰고 다시 읽지 않고 바로 냈어요. 무엇을 하면 좋을까요?","options":[{"t":"다시 한번 읽고 부족한 부분이 있으면 고쳐 써요","correct":true,"mis_target":"K1-2-u3-X17"},{"t":"그대로 내도 돼요","mis":"K1-2-u3-X17"},{"t":"친구 것과 누가 잘 썼는지 견줘요","mis":"K1-2-u3-X08"}],"explanation":["103쪽 점검 물음으로 확인해요.","소리 내어 읽으면 빠진 곳이 보여요.","붙임 13에 고쳐 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L10_challenge#6','kor',1,2,'u3','L10','g1_2_kor_u3_L10_challenge','lesson_challenge','K1-2-u3-C6',3,'match','auto','『국어』 103쪽 — 점검 물음과 「아니요」일 때 고쳐 쓰는 방법을 이어 보세요.','{}'::text[],false,'{"seq":6,"concept":"K1-2-u3-C6","difficulty":3,"kind":"match","stem":"『국어』 103쪽 — 점검 물음과 「아니요」일 때 고쳐 쓰는 방법을 이어 보세요.","pairs":[{"l":"날짜와 요일, 날씨를 썼나요?","r":"날짜와 요일, 날씨를 확인해서 쓴다."},{"l":"경험한 일을 그림으로 잘 나타냈나요?","r":"가장 기억에 남는 장면을 정해 그림으로 그린다."},{"l":"경험한 일을 글로 잘 나타냈나요?","r":"누구와 어디에서 무엇을 했는지 자세히 쓴다."},{"l":"생각이나 느낌이 잘 드러났나요?","r":"생각이나 느낌을 문장으로 쓴다."}],"mis":"K1-2-u3-X17","explanation":["물음마다 고치는 방법이 있어요.","다시 한번 읽고 부족한 부분을 고쳐 써요.","103쪽 점검이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L10_challenge#7','kor',1,2,'u3','L10','g1_2_kor_u3_L10_challenge','lesson_challenge','K1-2-u3-C6',3,'mc','auto','지도서 161쪽 — 친구와 그림일기를 바꾸어 읽고 해 줄 칭찬하는 말은?',ARRAY['K1-2-u3-X18','K1-2-u3-X08']::text[],false,'{"seq":7,"concept":"K1-2-u3-C6","difficulty":3,"kind":"mc","stem":"지도서 161쪽 — 친구와 그림일기를 바꾸어 읽고 해 줄 칭찬하는 말은?","options":[{"t":"직접 한 말을 사용해서 실감이 나.","correct":true},{"t":"글씨가 삐뚤어서 별로야.","mis":"K1-2-u3-X18"},{"t":"내 일기가 더 잘 썼어.","mis":"K1-2-u3-X08"}],"explanation":["좋은 점을 찾아 칭찬해요.","빠진 내용은 친절하게 알려 줘요.","바꾸어 읽기 활동이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L10_challenge#8','kor',1,2,'u3','L10','g1_2_kor_u3_L10_challenge','lesson_challenge','K1-2-u3-C6',4,'sa','auto','『국어』 108쪽 — 「현지가 ◯◯ 닦습니다.」 빈칸에 「무엇을」에 해당하는 말을 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K1-2-u3-C6","difficulty":4,"kind":"sa","stem":"『국어』 108쪽 — 「현지가 ◯◯ 닦습니다.」 빈칸에 「무엇을」에 해당하는 말을 쓰세요.","answer":["거울을","거울"],"explanation":["현지가 거울을 닦아요.","「무엇을」 자리에 대상을 넣어요.","108쪽 그림을 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L10_challenge#9','kor',1,2,'u3','L10','g1_2_kor_u3_L10_challenge','lesson_challenge','K1-2-u3-C6',4,'essay','teacher','『국어』 101쪽 — 어제 있었던 일 가운데 기억에 남는 일을 「언제·어디에서 / 누구와 / 무슨 일 / 생각이나 느낌」으로 정리해 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K1-2-u3-C6","difficulty":4,"kind":"essay","stem":"『국어』 101쪽 — 어제 있었던 일 가운데 기억에 남는 일을 「언제·어디에서 / 누구와 / 무슨 일 / 생각이나 느낌」으로 정리해 쓰세요.","answer_guide":{"answer":"예: 어제 저녁, 집에서 / 동생과 / 동화책을 읽었다 / 동생이 재미있다고 웃어서 뿌듯했다. — 네 가지가 들어가면 맞아요.","scoring_points":["언제·어디에서를 썼는가","누구와·무슨 일을 썼는가","생각이나 느낌을 썼는가"]},"explanation":["101쪽 네 물음에 차례로 답해요.","기억에 남는 일 하나를 골라요.","느낌도 꼭 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L10_challenge#10','kor',1,2,'u3','L10','g1_2_kor_u3_L10_challenge','lesson_challenge','K1-2-u3-C6',4,'essay','teacher','지도서 160쪽 — 오늘 날씨를 나만의 재미있는 말로 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"K1-2-u3-C6","difficulty":4,"kind":"essay","stem":"지도서 160쪽 — 오늘 날씨를 나만의 재미있는 말로 써 보세요.","answer_guide":{"answer":"예: 해님이 방긋 / 바람 때문에 추움 / 구름이 솜사탕처럼 몽실몽실 — 날씨가 드러나면 맞아요.","scoring_points":["날씨가 드러나는가","나만의 표현인가","짧게 썼는가"]},"explanation":["「맑음」처럼 간단히 써도 되고 재미있게 꾸며도 돼요.","국어활동 39쪽 「눈이 와서 신나는 날」도 본보기예요.","오늘 하늘을 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L12_basic#1','kor',1,2,'u3','L12','g1_2_kor_u3_L12_basic','lesson_basic','K1-2-u3-C7',1,'mc','auto','『국어』 104쪽 ① — 표의 「언제」 칸에 알맞은 것은?',ARRAY['K1-2-u3-X13']::text[],false,'{"seq":1,"concept":"K1-2-u3-C7","difficulty":1,"kind":"mc","stem":"『국어』 104쪽 ① — 표의 「언제」 칸에 알맞은 것은?","options":[{"t":"어제 저녁","correct":true},{"t":"동생과","mis":"K1-2-u3-X13"},{"t":"고양이와 공놀이를 했다","mis":"K1-2-u3-X13"}],"explanation":["「언제」에는 때를 써요.","「동생과」는 누구와, 「공놀이」는 있었던 일이에요.","104쪽 표예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L12_basic#2','kor',1,2,'u3','L12','g1_2_kor_u3_L12_basic','lesson_basic','K1-2-u3-C7',1,'mc','auto','『국어』 104쪽 — 그림으로 나타낼 장면은 어떻게 고를까요?',ARRAY['K1-2-u3-X13']::text[],false,'{"seq":2,"concept":"K1-2-u3-C7","difficulty":1,"kind":"mc","stem":"『국어』 104쪽 — 그림으로 나타낼 장면은 어떻게 고를까요?","options":[{"t":"경험을 잘 보여 줄 수 있는 한 장면을 골라요","correct":true},{"t":"있었던 일을 처음부터 끝까지 다 그려요","mis":"K1-2-u3-X13"},{"t":"아무 장면이나 골라요","mis":"K1-2-u3-X13"}],"explanation":["있었던 일을 모두 그릴 수는 없어요.","특징이 잘 드러나는 한 장면을 골라요.","104쪽 표의 마지막 칸이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L12_basic#3','kor',1,2,'u3','L12','g1_2_kor_u3_L12_basic','lesson_basic','K1-2-u3-C7',1,'mc','auto','친구의 작품을 감상할 때 알맞은 태도는?',ARRAY['K1-2-u3-X08','K1-2-u3-X18']::text[],false,'{"seq":3,"concept":"K1-2-u3-C7","difficulty":1,"kind":"mc","stem":"친구의 작품을 감상할 때 알맞은 태도는?","options":[{"t":"재미있는 점이나 잘한 점을 찾아 칭찬해요","correct":true},{"t":"누가 제일 잘했는지 가려요","mis":"K1-2-u3-X08"},{"t":"틀린 곳만 찾아 놀려요","mis":"K1-2-u3-X18"}],"explanation":["서로 칭찬하며 감상을 나눠요.","순위를 매기거나 놀리지 않아요.","지도서 163쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L12_basic#4','kor',1,2,'u3','L12','g1_2_kor_u3_L12_basic','lesson_basic','K1-2-u3-C7',1,'mc','auto','그림 그리기가 어려울 때에는 어떻게 할까요?',ARRAY['K1-2-u3-X10']::text[],false,'{"seq":4,"concept":"K1-2-u3-C7","difficulty":1,"kind":"mc","stem":"그림 그리기가 어려울 때에는 어떻게 할까요?","options":[{"t":"간단한 선 그림으로 만화처럼 그려도 돼요","correct":true},{"t":"그림 칸을 비워 둬요","mis":"K1-2-u3-X10"},{"t":"활동을 그만둬요","mis":"K1-2-u3-X10"}],"explanation":["표현의 부담을 덜어도 괜찮아요.","내 경험이 보이는 것이 중요해요.","지도서 163쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L12_basic#5','kor',1,2,'u3','L12','g1_2_kor_u3_L12_basic','lesson_basic','K1-2-u3-C7',2,'match','auto','『국어』 104쪽 ① — 표에 정리한 내용을 이어 보세요.','{}'::text[],false,'{"seq":5,"concept":"K1-2-u3-C7","difficulty":2,"kind":"match","stem":"『국어』 104쪽 ① — 표에 정리한 내용을 이어 보세요.","pairs":[{"l":"언제","r":"어제 저녁"},{"l":"어디에서","r":"우리 집 거실"},{"l":"누구와","r":"동생과"},{"l":"있었던 일","r":"고양이와 공놀이를 했다."}],"mis":"K1-2-u3-X13","explanation":["언제·어디에서·누구와를 정리해요.","있었던 일을 쓰면 그림 장면을 고르기 쉬워요.","104쪽 표예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L12_basic#6','kor',1,2,'u3','L12','g1_2_kor_u3_L12_basic','lesson_basic','K1-2-u3-C7',2,'mc','auto','「우리 집 고양이」라는 제목에 어울리는 내용은?',ARRAY['K1-2-u3-X13']::text[],false,'{"seq":6,"concept":"K1-2-u3-C7","difficulty":2,"kind":"mc","stem":"「우리 집 고양이」라는 제목에 어울리는 내용은?","options":[{"t":"고양이와 놀았던 일과 고양이가 귀여운 점","correct":true},{"t":"자전거를 탄 일","mis":"K1-2-u3-X13"},{"t":"라면을 끓인 일","mis":"K1-2-u3-X13"}],"explanation":["제목에 알맞은 내용을 써야 해요.","고양이와 상관없는 일은 어울리지 않아요.","지도서 163쪽이에요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"나는 ‘우리 집 고양이’라고 제목을 정했어."},{"who":"친구 2","text":"재미있겠다. 어떤 내용을 쓸 거니?"},{"who":"친구 1","text":"어제 고양이랑 놀았던 일을 쓸 거야. 또 우리 집 고양이가 얼마나 귀여운지도 써야지."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L12_basic#7','kor',1,2,'u3','L12','g1_2_kor_u3_L12_basic','lesson_basic','K1-2-u3-C7',2,'mc','auto','지도서 163쪽 — 작품을 전시할 때 「전시회 해설자」가 되면 무엇을 하나요?',ARRAY['K1-2-u3-X08','K1-2-u3-X18']::text[],false,'{"seq":7,"concept":"K1-2-u3-C7","difficulty":2,"kind":"mc","stem":"지도서 163쪽 — 작품을 전시할 때 「전시회 해설자」가 되면 무엇을 하나요?","options":[{"t":"내 작품에 담긴 일을 친구들에게 소개해요","correct":true},{"t":"친구 작품의 순위를 매겨요","mis":"K1-2-u3-X08"},{"t":"친구 작품을 고쳐 그려요","mis":"K1-2-u3-X18"}],"explanation":["이 작품의 작가는 바로 나예요.","작품을 설명하며 대화를 나눠요.","③ 활동이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L12_basic#8','kor',1,2,'u3','L12','g1_2_kor_u3_L12_basic','lesson_basic','K1-2-u3-C7',2,'mc','auto','지도서 164쪽 예시 1 — 한 모둠이 어제 있었던 일을 몸으로 표현하면 다른 모둠은?',ARRAY['K1-2-u3-X08','K1-2-u3-X18']::text[],false,'{"seq":8,"concept":"K1-2-u3-C7","difficulty":2,"kind":"mc","stem":"지도서 164쪽 예시 1 — 한 모둠이 어제 있었던 일을 몸으로 표현하면 다른 모둠은?","options":[{"t":"어떤 일인지 알아맞혀요","correct":true},{"t":"누가 제일 잘했는지 뽑아요","mis":"K1-2-u3-X08"},{"t":"따라 하며 놀려요","mis":"K1-2-u3-X18"}],"explanation":["몸으로 표현한 일을 알아맞혀요.","서로 경험을 나누는 놀이예요.","우리 반에서 정한 활동이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L12_basic#9','kor',1,2,'u3','L12','g1_2_kor_u3_L12_basic','lesson_basic','K1-2-u3-C7',2,'ox','auto','전시된 친구 작품은 마음대로 만지거나 고쳐도 돼요.',ARRAY['K1-2-u3-X18']::text[],false,'{"seq":9,"concept":"K1-2-u3-C7","difficulty":2,"kind":"ox","stem":"전시된 친구 작품은 마음대로 만지거나 고쳐도 돼요.","answer":"X","reason_options":[{"t":"친구가 정성껏 만든 작품이니 눈으로 보고 좋은 점을 말해야 하니까","correct":true},{"t":"같은 반 친구 것이니 괜찮으니까","mis":"K1-2-u3-X18"}],"mis":"K1-2-u3-X18","explanation":["작품에 손대지 않고 감상해요.","좋았던 점을 짚어 말해요.","전시 예절이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L12_basic#10','kor',1,2,'u3','L12','g1_2_kor_u3_L12_basic','lesson_basic','K1-2-u3-C7',3,'mc','auto','지도서 163쪽 — 내 글과 그림을 전시하면 좋은 점은?',ARRAY['K1-2-u3-X08','K1-2-u3-X13']::text[],false,'{"seq":10,"concept":"K1-2-u3-C7","difficulty":3,"kind":"mc","stem":"지도서 163쪽 — 내 글과 그림을 전시하면 좋은 점은?","options":[{"t":"내 작품을 보는 사람을 만나 경험을 나눌 수 있어요","correct":true},{"t":"누가 제일 잘했는지 정할 수 있어요","mis":"K1-2-u3-X08"},{"t":"친구 것을 베낄 수 있어요","mis":"K1-2-u3-X13"}],"explanation":["쓴 글을 세상으로 내보내는 것이에요.","비슷한 경험을 나누는 대화가 생겨요.","「출판하기」예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L12_challenge#1','kor',1,2,'u3','L12','g1_2_kor_u3_L12_challenge','lesson_challenge','K1-2-u3-C7',2,'mc','auto','지도서 165쪽 예시 2 — 오늘 있었던 일을 떠올리는 표에 쓸 것은?',ARRAY['K1-2-u3-X13','K1-2-u3-X12']::text[],false,'{"seq":1,"concept":"K1-2-u3-C7","difficulty":2,"kind":"mc","stem":"지도서 165쪽 예시 2 — 오늘 있었던 일을 떠올리는 표에 쓸 것은?","options":[{"t":"언제 · 누구와 · 무엇을 했다","correct":true},{"t":"몇 쪽 · 무슨 색","mis":"K1-2-u3-X13"},{"t":"이름 · 시간표","mis":"K1-2-u3-X12"}],"explanation":["언제, 누구와, 무엇을 했는지 써요.","쪽수나 시간표는 경험한 일과 상관없어요.","예시 2의 표예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L12_challenge#2','kor',1,2,'u3','L12','g1_2_kor_u3_L12_challenge','lesson_challenge','K1-2-u3-C7',2,'mc','auto','친구 작품에서 무엇이 좋았는지 말한 것은?',ARRAY['K1-2-u3-X18','K1-2-u3-X08']::text[],false,'{"seq":2,"concept":"K1-2-u3-C7","difficulty":2,"kind":"mc","stem":"친구 작품에서 무엇이 좋았는지 말한 것은?","options":[{"t":"고양이가 웃는 얼굴이 재미있어.","correct":true},{"t":"그림을 못 그렸네.","mis":"K1-2-u3-X18"},{"t":"내 작품이 더 좋아.","mis":"K1-2-u3-X08"}],"explanation":["무엇이 좋았는지 한 가지를 짚어 말해요.","놀리거나 견주지 않아요.","감상 예절이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L12_challenge#3','kor',1,2,'u3','L12','g1_2_kor_u3_L12_challenge','lesson_challenge','K1-2-u3-C7',3,'error','auto','감상 시간에 「누가 제일 잘 그렸는지 뽑자.」라고 했어요. 무엇이 잘못되었나요?',ARRAY['K1-2-u3-X08','K1-2-u3-X18']::text[],false,'{"seq":3,"concept":"K1-2-u3-C7","difficulty":3,"kind":"error","stem":"감상 시간에 「누가 제일 잘 그렸는지 뽑자.」라고 했어요. 무엇이 잘못되었나요?","options":[{"t":"순위를 가리는 대신 친구마다 좋은 점을 찾아 칭찬해요","correct":true,"mis_target":"K1-2-u3-X08"},{"t":"좋은 생각이에요","mis":"K1-2-u3-X08"},{"t":"제일 못한 작품도 뽑아요","mis":"K1-2-u3-X18"}],"explanation":["감상은 잘한 점을 칭찬하고 경험을 나누는 시간이에요.","순위를 매기면 서로 속상해요.","지도서 163쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L12_challenge#4','kor',1,2,'u3','L12','g1_2_kor_u3_L12_challenge','lesson_challenge','K1-2-u3-C7',3,'error','auto','친구 작품을 보고 「그림을 못 그렸네.」라고 했어요. 무엇이 잘못되었나요?',ARRAY['K1-2-u3-X18']::text[],false,'{"seq":4,"concept":"K1-2-u3-C7","difficulty":3,"kind":"error","stem":"친구 작품을 보고 「그림을 못 그렸네.」라고 했어요. 무엇이 잘못되었나요?","options":[{"t":"그림 솜씨가 아니라 무엇이 좋았는지 말해요","correct":true,"mis_target":"K1-2-u3-X18"},{"t":"솔직하게 잘 말했어요","mis":"K1-2-u3-X18"},{"t":"더 크게 말해야 해요","mis":"K1-2-u3-X18"}],"explanation":["그림 솜씨를 겨루는 것이 아니에요.","재미있는 점이나 기억에 남는 점을 말해요.","감상 예절이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L12_challenge#5','kor',1,2,'u3','L12','g1_2_kor_u3_L12_challenge','lesson_challenge','K1-2-u3-C7',3,'error','auto','그림에는 놀이터를 그리고, 글에는 생일잔치를 썼어요. 무엇이 잘못되었나요?',ARRAY['K1-2-u3-X13','K1-2-u3-X10']::text[],false,'{"seq":5,"concept":"K1-2-u3-C7","difficulty":3,"kind":"error","stem":"그림에는 놀이터를 그리고, 글에는 생일잔치를 썼어요. 무엇이 잘못되었나요?","options":[{"t":"글과 그림이 같은 일을 담아야 해요","correct":true,"mis_target":"K1-2-u3-X13"},{"t":"잘했어요 — 다를수록 좋아요","mis":"K1-2-u3-X13"},{"t":"색칠을 더 해야 해요","mis":"K1-2-u3-X10"}],"explanation":["그림은 글의 장면을 보여 줘요.","같은 일의 한 장면을 그려요.","104쪽 활동이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L12_challenge#6','kor',1,2,'u3','L12','g1_2_kor_u3_L12_challenge','lesson_challenge','K1-2-u3-C7',3,'match','auto','『국어』 104쪽 — 활동 순서와 할 일을 이어 보세요.','{}'::text[],false,'{"seq":6,"concept":"K1-2-u3-C7","difficulty":3,"kind":"match","stem":"『국어』 104쪽 — 활동 순서와 할 일을 이어 보세요.","pairs":[{"l":"①","r":"친구와 있었던 일 가운데 기억에 남는 일 떠올리기"},{"l":"②","r":"떠올린 일을 글과 그림으로 나타내기"},{"l":"③","r":"교실에 전시하고 감상 나누기"}],"mis":"K1-2-u3-X13","explanation":["떠올리기 → 글과 그림으로 나타내기 → 전시하고 감상 나누기예요.","차례대로 해요.","104쪽 활동이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L12_challenge#7','kor',1,2,'u3','L12','g1_2_kor_u3_L12_challenge','lesson_challenge','K1-2-u3-C7',3,'mc','auto','「어제 고양이랑 놀았던 일」에 어울리는 제목은?',ARRAY['K1-2-u3-X12']::text[],false,'{"seq":7,"concept":"K1-2-u3-C7","difficulty":3,"kind":"mc","stem":"「어제 고양이랑 놀았던 일」에 어울리는 제목은?","options":[{"t":"우리 집 고양이","correct":true},{"t":"우리 반 시간표","mis":"K1-2-u3-X12"},{"t":"오늘의 준비물","mis":"K1-2-u3-X12"}],"explanation":["기억에 남는 일을 제목으로 지을 수 있어요.","시간표나 준비물은 어울리지 않아요.","지도서 163쪽이에요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"나는 ‘우리 집 고양이’라고 제목을 정했어."},{"who":"친구 2","text":"재미있겠다. 어떤 내용을 쓸 거니?"},{"who":"친구 1","text":"어제 고양이랑 놀았던 일을 쓸 거야. 또 우리 집 고양이가 얼마나 귀여운지도 써야지."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L12_challenge#8','kor',1,2,'u3','L12','g1_2_kor_u3_L12_challenge','lesson_challenge','K1-2-u3-C7',4,'sa','auto','「우리 집 고양이」라고 제목을 정한 친구는 무엇과 놀았던 일을 쓸까요? 한 낱말로 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K1-2-u3-C7","difficulty":4,"kind":"sa","stem":"「우리 집 고양이」라고 제목을 정한 친구는 무엇과 놀았던 일을 쓸까요? 한 낱말로 쓰세요.","answer":["고양이"],"explanation":["어제 고양이랑 놀았던 일을 쓴대요.","고양이가 얼마나 귀여운지도 쓴대요.","친구의 말을 읽어 봐요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"나는 ‘우리 집 고양이’라고 제목을 정했어."},{"who":"친구 2","text":"재미있겠다. 어떤 내용을 쓸 거니?"},{"who":"친구 1","text":"어제 고양이랑 놀았던 일을 쓸 거야. 또 우리 집 고양이가 얼마나 귀여운지도 써야지."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L12_challenge#9','kor',1,2,'u3','L12','g1_2_kor_u3_L12_challenge','lesson_challenge','K1-2-u3-C7',4,'essay','teacher','『국어』 104쪽 ① — 친구와 있었던 일 가운데 기억에 남는 일을 「언제 · 어디에서 · 누구와 · 있었던 일」로 정리해 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K1-2-u3-C7","difficulty":4,"kind":"essay","stem":"『국어』 104쪽 ① — 친구와 있었던 일 가운데 기억에 남는 일을 「언제 · 어디에서 · 누구와 · 있었던 일」로 정리해 쓰세요.","answer_guide":{"answer":"예: 지난 토요일 · 놀이터에서 · 지우와 · 시소를 탔다. — 네 칸이 다 들어가면 맞아요.","scoring_points":["언제·어디에서를 썼는가","누구와를 썼는가","있었던 일을 썼는가"]},"explanation":["표의 네 칸을 채워요.","그림으로 나타낼 장면도 생각해 봐요.","104쪽 표예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_L12_challenge#10','kor',1,2,'u3','L12','g1_2_kor_u3_L12_challenge','lesson_challenge','K1-2-u3-C7',4,'essay','teacher','친구의 글과 그림을 감상하고 칭찬하는 말을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K1-2-u3-C7","difficulty":4,"kind":"essay","stem":"친구의 글과 그림을 감상하고 칭찬하는 말을 쓰세요.","answer_guide":{"answer":"예: 고양이 그림이 귀엽고, 공놀이한 일을 자세히 써서 재미있었어. — 좋았던 점을 짚어 말하면 맞아요.","scoring_points":["좋았던 점을 짚었는가","놀리거나 견주지 않았는가","문장이 자연스러운가"]},"explanation":["재미있는 점이나 기억에 남는 점을 말해요.","잘한 점을 칭찬해요.","지도서 163쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_review_a#1','kor',1,2,'u3','','g1_2_kor_u3_review_a','unit_review','K1-2-u3-C1',1,'mc','auto','바른 자세로 발표하는 방법은?',ARRAY['K1-2-u3-X02','K1-2-u3-X01']::text[],false,'{"seq":1,"concept":"K1-2-u3-C1","difficulty":1,"kind":"mc","stem":"바른 자세로 발표하는 방법은?","options":[{"t":"허리를 펴고 바른 자세로 서서 말한다","correct":true},{"t":"허리를 굽히고 바닥을 보며 말한다","mis":"K1-2-u3-X02"},{"t":"소리를 있는 힘껏 지른다","mis":"K1-2-u3-X01"}],"explanation":["허리를 펴고 바르게 서요.","바닥을 보거나 소리를 지르지 않아요.","85쪽 2번이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_review_a#2','kor',1,2,'u3','','g1_2_kor_u3_review_a','unit_review','K1-2-u3-C2',1,'mc','auto','『국어』 106쪽 — 「바른 자세로 듣기」에 알맞은 것은?',ARRAY['K1-2-u3-X04']::text[],false,'{"seq":2,"concept":"K1-2-u3-C2","difficulty":1,"kind":"mc","stem":"『국어』 106쪽 — 「바른 자세로 듣기」에 알맞은 것은?","options":[{"t":"말하는 사람을 바라본다","correct":true},{"t":"듣는 사람을 바라본다","mis":"K1-2-u3-X04"},{"t":"또박또박 말한다","mis":"K1-2-u3-X04"}],"explanation":["들을 때에는 말하는 사람을 바라봐요.","듣는 사람을 바라보는 것은 말할 때예요.","106쪽 1번이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_review_a#3','kor',1,2,'u3','','g1_2_kor_u3_review_a','unit_review','K1-2-u3-C5',1,'mc','auto','그림일기 맨 위에 쓰는 것은?',ARRAY['K1-2-u3-X11','K1-2-u3-X12']::text[],false,'{"seq":3,"concept":"K1-2-u3-C5","difficulty":1,"kind":"mc","stem":"그림일기 맨 위에 쓰는 것은?","options":[{"t":"날짜와 요일, 날씨","correct":true},{"t":"생각이나 느낌","mis":"K1-2-u3-X11"},{"t":"시간표","mis":"K1-2-u3-X12"}],"explanation":["맨 윗줄에 날짜와 요일, 날씨를 써요.","시간표는 그림일기에 들어가지 않아요.","96쪽 찬호의 일기예요."],"asset":{"type":"diary","date":"20○○년 10월 24일 일요일","weather":"해가 쨍쨍한 날","picture":"🍎🌳👵🧒","lines":["과수원을 하시는 할머니 댁에 놀러 갔다.","나와 동생은 빨갛게 익은 사과를 땄다.","사과를 직접 따 보니 정말 재미있었다."],"name":"찬호"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_review_a#4','kor',1,2,'u3','','g1_2_kor_u3_review_a','unit_review','K1-2-u3-C5',1,'mc','auto','『국어』 107쪽 — 그림일기에 들어가야 할 내용은?',ARRAY['K1-2-u3-X12']::text[],false,'{"seq":4,"concept":"K1-2-u3-C5","difficulty":1,"kind":"mc","stem":"『국어』 107쪽 — 그림일기에 들어가야 할 내용은?","options":[{"t":"날씨","correct":true},{"t":"식단","mis":"K1-2-u3-X12"},{"t":"시간표","mis":"K1-2-u3-X12"}],"explanation":["날씨는 그림일기에 꼭 들어가요.","식단과 시간표는 들어가지 않아요.","107쪽 3번이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_review_a#5','kor',1,2,'u3','','g1_2_kor_u3_review_a','unit_review','K1-2-u3-C3',1,'mc','auto','『국어』 88쪽 — 기지개 켜는 아이 그림에 어울리는 문장은?',ARRAY['K1-2-u3-X07']::text[],false,'{"seq":5,"concept":"K1-2-u3-C3","difficulty":1,"kind":"mc","stem":"『국어』 88쪽 — 기지개 켜는 아이 그림에 어울리는 문장은?","options":[{"t":"일곱 시에 일어났다.","correct":true},{"t":"된장찌개를 먹었다.","mis":"K1-2-u3-X07"},{"t":"친구를 만났다.","mis":"K1-2-u3-X07"}],"explanation":["일곱 시에 일어난 그림이에요.","다른 그림의 문장이에요.","88쪽이에요."],"asset":{"type":"scene","icon":"⏰🥱"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_review_a#6','kor',1,2,'u3','','g1_2_kor_u3_review_a','unit_review','K1-2-u3-C4',1,'mc','auto','「치즈 농장에 가서 치즈를 만든 일」은 어떤 느낌의 일일까요?',ARRAY['K1-2-u3-X09']::text[],false,'{"seq":6,"concept":"K1-2-u3-C4","difficulty":1,"kind":"mc","stem":"「치즈 농장에 가서 치즈를 만든 일」은 어떤 느낌의 일일까요?","options":[{"t":"재미있었던 일","correct":true},{"t":"슬펐던 일","mis":"K1-2-u3-X09"},{"t":"놀랐던 일","mis":"K1-2-u3-X09"}],"explanation":["93쪽 예시에서 재미있었던 일 칸에 썼어요.","그때의 느낌에 따라 나눠요.","93쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_review_a#7','kor',1,2,'u3','','g1_2_kor_u3_review_a','unit_review','K1-2-u3-C6',1,'mc','auto','『국어』 108쪽 — 「재현이가 ___ 읽습니다.」에 알맞은 말은?',ARRAY['K1-2-u3-X19']::text[],false,'{"seq":7,"concept":"K1-2-u3-C6","difficulty":1,"kind":"mc","stem":"『국어』 108쪽 — 「재현이가 ___ 읽습니다.」에 알맞은 말은?","options":[{"t":"책을","correct":true},{"t":"책이","mis":"K1-2-u3-X19"},{"t":"의자를","mis":"K1-2-u3-X19"}],"explanation":["무엇을 읽는지 「책을」을 넣어요.","「책이」는 「무엇을」 자리가 아니에요.","108쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_review_a#8','kor',1,2,'u3','','g1_2_kor_u3_review_a','unit_review','K1-2-u3-C2',1,'mc','auto','『국어』 106쪽 2번 — 바른 자세로 들어야 할 때는?',ARRAY['K1-2-u3-X04']::text[],false,'{"seq":8,"concept":"K1-2-u3-C2","difficulty":1,"kind":"mc","stem":"『국어』 106쪽 2번 — 바른 자세로 들어야 할 때는?","options":[{"t":"수업 시간에 친구가 발표할 때","correct":true},{"t":"혼자서 노래를 부를 때","mis":"K1-2-u3-X04"},{"t":"혼자서 그림을 그릴 때","mis":"K1-2-u3-X04"}],"explanation":["친구가 발표할 때 바른 자세로 들어요.","혼자 있을 때와 달라요.","106쪽 2번이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_review_a#9','kor',1,2,'u3','','g1_2_kor_u3_review_a','unit_review','K1-2-u3-C1',2,'match','auto','『국어』 85쪽 2번 — 바른 자세로 발표하는 방법을 이어 보세요.','{}'::text[],false,'{"seq":9,"concept":"K1-2-u3-C1","difficulty":2,"kind":"match","stem":"『국어』 85쪽 2번 — 바른 자세로 발표하는 방법을 이어 보세요.","pairs":[{"l":"🧍 허리를 쭉 편 아이","r":"허리를 펴고 바른 자세로 서서 말한다."},{"l":"🗣️ 또렷하게 말하는 아이","r":"알맞은 크기의 목소리로 또박또박 말한다."},{"l":"👀 친구들을 보는 아이","r":"듣는 사람을 바라보며 말한다."}],"mis":"K1-2-u3-X02","explanation":["세 가지 방법이에요.","모두 지키면 잘 전해져요.","85쪽 2번이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_review_a#10','kor',1,2,'u3','','g1_2_kor_u3_review_a','unit_review','K1-2-u3-C2',2,'mc','auto','『국어활동』 37쪽 — 선생님 말씀을 잘 들은 아이가 과자를 가져오는 방법은?',ARRAY['K1-2-u3-X04']::text[],false,'{"seq":10,"concept":"K1-2-u3-C2","difficulty":2,"kind":"mc","stem":"『국어활동』 37쪽 — 선생님 말씀을 잘 들은 아이가 과자를 가져오는 방법은?","options":[{"t":"통에 먹을 만큼만 담아 와요","correct":true},{"t":"봉지째 가져와요","mis":"K1-2-u3-X04"},{"t":"과자를 많이 사 와요","mis":"K1-2-u3-X04"}],"explanation":["쓰레기를 줄이려면 통에 먹을 만큼만 담아 오래요.","봉지째 가져오지 말라고 했어요.","선생님 말씀을 다시 읽어요."],"asset":{"type":"speech","turns":[{"who":"선생님","text":"내일은 현장 체험 학습을 가죠? 준비물을 안내할 테니 집중해서 잘 들어요."},{"who":"아이","text":"선생님, 내일 과자 가지고 와도 돼요?"},{"who":"선생님","text":"쓰레기를 줄이려면 과자는 봉지째 가져오지 말고 통에 먹을 만큼만 담아 오세요."},{"who":"선생님","text":"그리고 돗자리와 물도 준비해 주세요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
