INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_review_a#12','kor',1,2,'u3','','g1_2_kor_u3_review_a','unit_review','K1-2-u3-C5',2,'mc','auto','찬호의 그림일기 — 어디에서 있었던 일인가요?',ARRAY['K1-2-u3-X14']::text[],false,'{"seq":12,"concept":"K1-2-u3-C5","difficulty":2,"kind":"mc","stem":"찬호의 그림일기 — 어디에서 있었던 일인가요?","options":[{"t":"과수원을 하시는 할머니 댁","correct":true},{"t":"학교 운동장","mis":"K1-2-u3-X14"},{"t":"우리 집 거실","mis":"K1-2-u3-X14"}],"explanation":["「과수원을 하시는 할머니 댁에 놀러 갔다.」라고 썼어요.","어디에서 있었던 일인지 드러나 있어요.","첫째 줄을 읽어 봐요."],"asset":{"type":"diary","date":"20○○년 10월 24일 일요일","weather":"해가 쨍쨍한 날","picture":"🍎🌳👵🧒","lines":["과수원을 하시는 할머니 댁에 놀러 갔다.","나와 동생은 빨갛게 익은 사과를 땄다.","사과를 직접 따 보니 정말 재미있었다."],"name":"찬호"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
