INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_review_a#16','kor',1,2,'u3','','g1_2_kor_u3_review_a','unit_review','K1-2-u3-C3',2,'ox','auto','아침에 먹은 음식처럼 작은 일도 발표할 거리가 돼요.',ARRAY['K1-2-u3-X06']::text[],false,'{"seq":16,"concept":"K1-2-u3-C3","difficulty":2,"kind":"ox","stem":"아침에 먹은 음식처럼 작은 일도 발표할 거리가 돼요.","answer":"O","reason_options":[{"t":"「나는 ○○을/를 먹었다.」처럼 있었던 일을 문장으로 말할 수 있으니까","correct":true},{"t":"특별한 일만 발표할 수 있으니까","mis":"K1-2-u3-X06"}],"mis":"K1-2-u3-X06","explanation":["작은 일도 경험이에요.","문장으로 말하면 돼요.","지도서 144쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_review_a#17','kor',1,2,'u3','','g1_2_kor_u3_review_a','unit_review','K1-2-u3-C1',3,'error','auto','친구가 「제가 좋아하는 색은 파란색…….」이라고 발표했어요. 무엇이 잘못되었나요?',ARRAY['K1-2-u3-X01','K1-2-u3-X03']::text[],false,'{"seq":17,"concept":"K1-2-u3-C1","difficulty":3,"kind":"error","stem":"친구가 「제가 좋아하는 색은 파란색…….」이라고 발표했어요. 무엇이 잘못되었나요?","options":[{"t":"말끝을 흐렸어요 — 끝까지 분명하게 말해요","correct":true,"mis_target":"K1-2-u3-X01"},{"t":"잘 말했어요","mis":"K1-2-u3-X01"},{"t":"더 빨리 말해야 해요","mis":"K1-2-u3-X03"}],"explanation":["말끝을 흐리면 알아듣기 힘들어요.","「파란색입니다.」처럼 끝까지 말해요.","82쪽 ㉮예요."],"asset":{"type":"speech","turns":[{"who":"여자아이(㉮)","text":"제가 좋아하는 색은 파란색……."},{"who":"남자아이(생각)","text":"목소리가 작아서 잘 안 들려."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_review_a#18','kor',1,2,'u3','','g1_2_kor_u3_review_a','unit_review','K1-2-u3-C5',3,'error','auto','『국어』 98쪽 그림일기의 날짜와 요일 옆은 무엇이 잘못되었나요?',ARRAY['K1-2-u3-X11']::text[],false,'{"seq":18,"concept":"K1-2-u3-C5","difficulty":3,"kind":"error","stem":"『국어』 98쪽 그림일기의 날짜와 요일 옆은 무엇이 잘못되었나요?","options":[{"t":"날씨를 쓰지 않았어요","correct":true,"mis_target":"K1-2-u3-X11"},{"t":"요일을 쓰지 않았어요","mis":"K1-2-u3-X11"},{"t":"잘 썼어요","mis":"K1-2-u3-X11"}],"explanation":["날씨 칸이 비어 있어요.","날짜와 요일은 썼어요.","98쪽이에요."],"asset":{"type":"diary","date":"20○○년 10월 22일 화요일","weather":null,"picture":"🛏️😴","lines":["나는 오늘 아침에 일어나 밥을 먹고","학교에 가서 공부를 했다.","그리고 집에 와서 숙제를 하고 잤다."]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_review_a#19','kor',1,2,'u3','','g1_2_kor_u3_review_a','unit_review','K1-2-u3-C6',3,'error','auto','친구가 그림일기 글에 「좋았다.」만 썼어요. 무엇이 잘못되었나요?',ARRAY['K1-2-u3-X15','K1-2-u3-X11']::text[],false,'{"seq":19,"concept":"K1-2-u3-C6","difficulty":3,"kind":"error","stem":"친구가 그림일기 글에 「좋았다.」만 썼어요. 무엇이 잘못되었나요?","options":[{"t":"무엇을 했고 왜 좋았는지가 빠졌어요","correct":true,"mis_target":"K1-2-u3-X15"},{"t":"잘 썼어요","mis":"K1-2-u3-X15"},{"t":"날씨가 없어요","mis":"K1-2-u3-X11"}],"explanation":["경험한 일과 느낌을 자세히 써요.","까닭을 붙여요.","103쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_review_a#20','kor',1,2,'u3','','g1_2_kor_u3_review_a','unit_review','K1-2-u3-C4',3,'error','auto','그림 한 장에 입학식, 체육 대회, 현장 체험 학습을 모두 그렸어요. 무엇이 잘못되었나요?',ARRAY['K1-2-u3-X13','K1-2-u3-X10']::text[],false,'{"seq":20,"concept":"K1-2-u3-C4","difficulty":3,"kind":"error","stem":"그림 한 장에 입학식, 체육 대회, 현장 체험 학습을 모두 그렸어요. 무엇이 잘못되었나요?","options":[{"t":"가장 기억에 남는 한 장면만 골라 그려야 해요","correct":true,"mis_target":"K1-2-u3-X13"},{"t":"잘했어요","mis":"K1-2-u3-X13"},{"t":"색칠을 더 해야 해요","mis":"K1-2-u3-X10"}],"explanation":["있었던 일을 모두 그릴 수 없어요.","한 장면을 골라요.","94쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_review_a#21','kor',1,2,'u3','','g1_2_kor_u3_review_a','unit_review','K1-2-u3-C7',3,'error','auto','감상 시간에 「누가 제일 잘 그렸는지 뽑자.」라고 했어요. 무엇이 잘못되었나요?',ARRAY['K1-2-u3-X08','K1-2-u3-X18']::text[],false,'{"seq":21,"concept":"K1-2-u3-C7","difficulty":3,"kind":"error","stem":"감상 시간에 「누가 제일 잘 그렸는지 뽑자.」라고 했어요. 무엇이 잘못되었나요?","options":[{"t":"순위를 가리는 대신 친구마다 좋은 점을 찾아 칭찬해요","correct":true,"mis_target":"K1-2-u3-X08"},{"t":"좋은 생각이에요","mis":"K1-2-u3-X08"},{"t":"제일 못한 작품도 뽑아요","mis":"K1-2-u3-X18"}],"explanation":["감상은 칭찬하고 나누는 시간이에요.","순위를 매기지 않아요.","지도서 163쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_review_a#22','kor',1,2,'u3','','g1_2_kor_u3_review_a','unit_review','K1-2-u3-C5',3,'match','auto','『국어』 99쪽 — 주의할 점과 보기의 말을 이어 보세요.','{}'::text[],false,'{"seq":22,"concept":"K1-2-u3-C5","difficulty":3,"kind":"match","stem":"『국어』 99쪽 — 주의할 점과 보기의 말을 이어 보세요.","pairs":[{"l":"날짜와 요일, ___을/를 쓴다.","r":"날씨"},{"l":"___이/가 그림에 잘 드러나게 표현한다.","r":"경험한 일"},{"l":"경험한 일에 대한 ___을/를 쓴다.","r":"생각이나 느낌"}],"mis":"K1-2-u3-X11","explanation":["날씨·경험한 일이에요.","생각이나 느낌이에요.","99쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_review_a#23','kor',1,2,'u3','','g1_2_kor_u3_review_a','unit_review','K1-2-u3-C5',4,'sa','auto','찬호와 동생이 할머니 댁에서 딴 과일은 무엇인가요?','{}'::text[],false,'{"seq":23,"concept":"K1-2-u3-C5","difficulty":4,"kind":"sa","stem":"찬호와 동생이 할머니 댁에서 딴 과일은 무엇인가요?","answer":["사과"],"explanation":["빨갛게 익은 사과를 땄어요.","과수원을 하시는 할머니 댁이에요.","96쪽이에요."],"asset":{"type":"diary","date":"20○○년 10월 24일 일요일","weather":"해가 쨍쨍한 날","picture":"🍎🌳👵🧒","lines":["과수원을 하시는 할머니 댁에 놀러 갔다.","나와 동생은 빨갛게 익은 사과를 땄다.","사과를 직접 따 보니 정말 재미있었다."],"name":"찬호"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_review_a#24','kor',1,2,'u3','','g1_2_kor_u3_review_a','unit_review','K1-2-u3-C6',4,'essay','teacher','지도서 평가 — 재미있게 겪었던 일을 떠올려 그림일기의 글 부분을 쓰세요. (날짜와 요일, 날씨도 쓰세요.)','{}'::text[],false,'{"seq":24,"concept":"K1-2-u3-C6","difficulty":4,"kind":"essay","stem":"지도서 평가 — 재미있게 겪었던 일을 떠올려 그림일기의 글 부분을 쓰세요. (날짜와 요일, 날씨도 쓰세요.)","answer_guide":{"answer":"예: 10월 15일 목요일, 해님이 방긋 / 운동장에서 친구와 술래잡기를 했다. 술래를 피해 달리니 가슴이 두근두근하고 신났다. — 날짜·요일·날씨, 있었던 일, 느낌이 있으면 맞아요.","scoring_points":["날짜와 요일, 날씨를 썼는가","언제 어디에서 누구와 있었던 일인지 썼는가","생각이나 느낌을 썼는가"]},"explanation":["그림일기의 형식에 맞게 써요.","기억에 남는 일 하나를 골라요.","지도서 171쪽 평가예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_review_a#25','kor',1,2,'u3','','g1_2_kor_u3_review_a','unit_review','K1-2-u3-C1',4,'essay','teacher','지도서 평가 — 최근에 읽은 책을 친구들 앞에서 소개하려고 해요. 책 제목과 발표할 내용을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K1-2-u3-C1","difficulty":4,"kind":"essay","stem":"지도서 평가 — 최근에 읽은 책을 친구들 앞에서 소개하려고 해요. 책 제목과 발표할 내용을 쓰세요.","answer_guide":{"answer":"예: 책 제목 「○○○」 / 주인공이 길을 잃은 강아지를 도와주는 이야기예요. 마음이 따뜻해졌어요. — 제목, 내용, 느낌이 있으면 맞아요.","scoring_points":["책 제목을 썼는가","책 내용을 썼는가","생각이나 느낌을 썼는가"]},"explanation":["제목·내용·생각이나 느낌으로 나누어 떠올려요.","발표할 내용을 미리 써 두면 자신감이 생겨요.","지도서 169쪽 평가예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_review_b#1','kor',1,2,'u3','','g1_2_kor_u3_review_b','unit_review','K1-2-u3-C1',1,'mc','auto','바른 자세로 발표하는 방법은?',ARRAY['K1-2-u3-X01','K1-2-u3-X02']::text[],false,'{"seq":1,"concept":"K1-2-u3-C1","difficulty":1,"kind":"mc","stem":"바른 자세로 발표하는 방법은?","options":[{"t":"알맞은 크기의 목소리로 또박또박 말한다","correct":true},{"t":"작은 목소리로 말끝을 흐린다","mis":"K1-2-u3-X01"},{"t":"친구를 보지 않고 빨리 말한다","mis":"K1-2-u3-X02"}],"explanation":["알맞은 크기로 또박또박 말해요.","작게 말하거나 서두르면 알아듣기 힘들어요.","85쪽 2번이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_review_b#2','kor',1,2,'u3','','g1_2_kor_u3_review_b','unit_review','K1-2-u3-C2',1,'mc','auto','『국어』 106쪽 — 「바른 자세로 듣기」에 알맞은 것은?',ARRAY['K1-2-u3-X04']::text[],false,'{"seq":2,"concept":"K1-2-u3-C2","difficulty":1,"kind":"mc","stem":"『국어』 106쪽 — 「바른 자세로 듣기」에 알맞은 것은?","options":[{"t":"귀 기울여 듣는다","correct":true},{"t":"또박또박 말한다","mis":"K1-2-u3-X04"},{"t":"짝과 이야기한다","mis":"K1-2-u3-X04"}],"explanation":["들을 때에는 귀 기울여 들어요.","떠들면 잘 들을 수 없어요.","106쪽 1번이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_review_b#3','kor',1,2,'u3','','g1_2_kor_u3_review_b','unit_review','K1-2-u3-C5',1,'mc','auto','찬호가 그림일기를 쓴 날의 요일은?',ARRAY['K1-2-u3-X11']::text[],false,'{"seq":3,"concept":"K1-2-u3-C5","difficulty":1,"kind":"mc","stem":"찬호가 그림일기를 쓴 날의 요일은?","options":[{"t":"일요일","correct":true},{"t":"화요일","mis":"K1-2-u3-X11"},{"t":"금요일","mis":"K1-2-u3-X11"}],"explanation":["「10월 24일 일요일」이라고 썼어요.","맨 윗줄을 봐요.","날짜 옆에 요일을 써요."],"asset":{"type":"diary","date":"20○○년 10월 24일 일요일","weather":"해가 쨍쨍한 날","picture":"🍎🌳👵🧒","lines":["과수원을 하시는 할머니 댁에 놀러 갔다.","나와 동생은 빨갛게 익은 사과를 땄다.","사과를 직접 따 보니 정말 재미있었다."],"name":"찬호"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
