INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_review_b#9','kor',1,2,'u3','','g1_2_kor_u3_review_b','unit_review','K1-2-u3-C1',2,'match','auto','『국어』 106쪽 1번 — 말하기·듣기 방법을 이어 보세요.','{}'::text[],false,'{"seq":9,"concept":"K1-2-u3-C1","difficulty":2,"kind":"match","stem":"『국어』 106쪽 1번 — 말하기·듣기 방법을 이어 보세요.","pairs":[{"l":"듣는 사람을 바라본다.","r":"바른 자세로 말하기"},{"l":"귀 기울여 듣는다.","r":"바른 자세로 듣기"}],"mis":"K1-2-u3-X03","explanation":["듣는 사람을 바라보는 것은 말할 때예요.","귀 기울여 듣는 것은 들을 때예요.","106쪽 1번이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_review_b#10','kor',1,2,'u3','','g1_2_kor_u3_review_b','unit_review','K1-2-u3-C2',2,'mc','auto','『국어활동』 37쪽 — 선생님이 과자를 통에 담아 오라고 한 까닭은?',ARRAY['K1-2-u3-X04']::text[],false,'{"seq":10,"concept":"K1-2-u3-C2","difficulty":2,"kind":"mc","stem":"『국어활동』 37쪽 — 선생님이 과자를 통에 담아 오라고 한 까닭은?","options":[{"t":"쓰레기를 줄이려고","correct":true},{"t":"과자를 나눠 먹으려고","mis":"K1-2-u3-X04"},{"t":"가방을 가볍게 하려고","mis":"K1-2-u3-X04"}],"explanation":["「쓰레기를 줄이려면」이라고 말씀하셨어요.","끝까지 들어야 까닭을 알 수 있어요.","선생님 말씀을 다시 읽어요."],"asset":{"type":"speech","turns":[{"who":"선생님","text":"내일은 현장 체험 학습을 가죠? 준비물을 안내할 테니 집중해서 잘 들어요."},{"who":"아이","text":"선생님, 내일 과자 가지고 와도 돼요?"},{"who":"선생님","text":"쓰레기를 줄이려면 과자는 봉지째 가져오지 말고 통에 먹을 만큼만 담아 오세요."},{"who":"선생님","text":"그리고 돗자리와 물도 준비해 주세요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
