INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_review_b#16','kor',1,2,'u3','','g1_2_kor_u3_review_b','unit_review','K1-2-u3-C3',2,'ox','auto','경험한 일을 발표할 때에는 「재미있었다.」 한마디만 말해도 충분해요.',ARRAY['K1-2-u3-X07']::text[],false,'{"seq":16,"concept":"K1-2-u3-C3","difficulty":2,"kind":"ox","stem":"경험한 일을 발표할 때에는 「재미있었다.」 한마디만 말해도 충분해요.","answer":"X","reason_options":[{"t":"무슨 일이 어디에서 있었고 어떻게 되었는지 말해야 하니까","correct":true},{"t":"짧을수록 잘한 발표니까","mis":"K1-2-u3-X07"}],"mis":"K1-2-u3-X07","explanation":["느낌만 말하면 무슨 일인지 몰라요.","89쪽 세 물음에 답해요.","89쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_review_b#17','kor',1,2,'u3','','g1_2_kor_u3_review_b','unit_review','K1-2-u3-C1',3,'error','auto','발표할 때 허리를 굽히고 칠판만 보며 말했어요. 무엇이 잘못되었나요?',ARRAY['K1-2-u3-X02','K1-2-u3-X01']::text[],false,'{"seq":17,"concept":"K1-2-u3-C1","difficulty":3,"kind":"error","stem":"발표할 때 허리를 굽히고 칠판만 보며 말했어요. 무엇이 잘못되었나요?","options":[{"t":"허리를 펴고 듣는 사람을 바라보며 말해야 해요","correct":true,"mis_target":"K1-2-u3-X02"},{"t":"목소리만 더 크게 하면 돼요","mis":"K1-2-u3-X01"},{"t":"잘 발표했어요","mis":"K1-2-u3-X02"}],"explanation":["허리를 펴고 바르게 서요.","듣는 사람을 바라봐요.","85쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_review_b#18','kor',1,2,'u3','','g1_2_kor_u3_review_b','unit_review','K1-2-u3-C5',3,'error','auto','『국어』 98쪽 그림일기의 글은 무엇이 잘못되었나요?',ARRAY['K1-2-u3-X14','K1-2-u3-X11']::text[],false,'{"seq":18,"concept":"K1-2-u3-C5","difficulty":3,"kind":"error","stem":"『국어』 98쪽 그림일기의 글은 무엇이 잘못되었나요?","options":[{"t":"늘 하는 일을 늘어놓아 기억에 남는 일을 알 수 없어요","correct":true,"mis_target":"K1-2-u3-X14"},{"t":"그림이 없어요","mis":"K1-2-u3-X11"},{"t":"잘 썼어요","mis":"K1-2-u3-X14"}],"explanation":["늘 하는 일을 나열만 했어요.","기억에 남는 일 하나를 골라 써요.","98쪽이에요."],"asset":{"type":"diary","date":"20○○년 10월 22일 화요일","weather":null,"picture":"🛏️😴","lines":["나는 오늘 아침에 일어나 밥을 먹고","학교에 가서 공부를 했다.","그리고 집에 와서 숙제를 하고 잤다."]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_review_b#19','kor',1,2,'u3','','g1_2_kor_u3_review_b','unit_review','K1-2-u3-C6',3,'error','auto','친구가 그림만 꼼꼼히 색칠하다 글 칸을 비워 두었어요. 무엇이 잘못되었나요?',ARRAY['K1-2-u3-X16','K1-2-u3-X10','K1-2-u3-X11']::text[],false,'{"seq":19,"concept":"K1-2-u3-C6","difficulty":3,"kind":"error","stem":"친구가 그림만 꼼꼼히 색칠하다 글 칸을 비워 두었어요. 무엇이 잘못되었나요?","options":[{"t":"그림은 간단히 하고 글로 경험한 일과 느낌을 써야 해요","correct":true,"mis_target":"K1-2-u3-X16"},{"t":"잘했어요","mis":"K1-2-u3-X10"},{"t":"날씨를 지워야 해요","mis":"K1-2-u3-X11"}],"explanation":["글도 그림일기의 중요한 부분이에요.","그림에 시간을 다 쓰지 않아요.","지도서 159쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_review_b#20','kor',1,2,'u3','','g1_2_kor_u3_review_b','unit_review','K1-2-u3-C7',3,'error','auto','그림에는 놀이터를 그리고, 글에는 생일잔치를 썼어요. 무엇이 잘못되었나요?',ARRAY['K1-2-u3-X13','K1-2-u3-X10']::text[],false,'{"seq":20,"concept":"K1-2-u3-C7","difficulty":3,"kind":"error","stem":"그림에는 놀이터를 그리고, 글에는 생일잔치를 썼어요. 무엇이 잘못되었나요?","options":[{"t":"글과 그림이 같은 일을 담아야 해요","correct":true,"mis_target":"K1-2-u3-X13"},{"t":"잘했어요","mis":"K1-2-u3-X13"},{"t":"색칠을 더 해야 해요","mis":"K1-2-u3-X10"}],"explanation":["그림은 글의 장면을 보여 줘요.","같은 일의 한 장면을 그려요.","104쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_review_b#21','kor',1,2,'u3','','g1_2_kor_u3_review_b','unit_review','K1-2-u3-C7',3,'error','auto','친구 작품을 보고 「그림을 못 그렸네.」라고 했어요. 무엇이 잘못되었나요?',ARRAY['K1-2-u3-X18']::text[],false,'{"seq":21,"concept":"K1-2-u3-C7","difficulty":3,"kind":"error","stem":"친구 작품을 보고 「그림을 못 그렸네.」라고 했어요. 무엇이 잘못되었나요?","options":[{"t":"그림 솜씨가 아니라 무엇이 좋았는지 말해요","correct":true,"mis_target":"K1-2-u3-X18"},{"t":"솔직하게 잘 말했어요","mis":"K1-2-u3-X18"},{"t":"더 크게 말해야 해요","mis":"K1-2-u3-X18"}],"explanation":["그림 솜씨를 겨루지 않아요.","좋았던 점을 짚어 말해요.","감상 예절이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_review_b#22','kor',1,2,'u3','','g1_2_kor_u3_review_b','unit_review','K1-2-u3-C6',3,'match','auto','『국어』 103쪽 — 점검 물음과 고쳐 쓰는 방법을 이어 보세요.','{}'::text[],false,'{"seq":22,"concept":"K1-2-u3-C6","difficulty":3,"kind":"match","stem":"『국어』 103쪽 — 점검 물음과 고쳐 쓰는 방법을 이어 보세요.","pairs":[{"l":"날짜와 요일, 날씨를 썼나요?","r":"날짜와 요일, 날씨를 확인해서 쓴다."},{"l":"경험한 일을 글로 잘 나타냈나요?","r":"누구와 어디에서 무엇을 했는지 자세히 쓴다."},{"l":"생각이나 느낌이 잘 드러났나요?","r":"생각이나 느낌을 문장으로 쓴다."}],"mis":"K1-2-u3-X17","explanation":["물음마다 고치는 방법이 있어요.","다시 읽고 고쳐 써요.","103쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_review_b#23','kor',1,2,'u3','','g1_2_kor_u3_review_b','unit_review','K1-2-u3-C1',4,'sa','auto','『국어』 85쪽 — 남자아이가 탐험해 보고 싶은 곳은 어디인가요?','{}'::text[],false,'{"seq":23,"concept":"K1-2-u3-C1","difficulty":4,"kind":"sa","stem":"『국어』 85쪽 — 남자아이가 탐험해 보고 싶은 곳은 어디인가요?","answer":["북극"],"explanation":["북극을 탐험해 보고 싶다고 했어요.","또박또박 말해서 잘 들렸어요.","85쪽이에요."],"asset":{"type":"speech","turns":[{"who":"남자아이","text":"제 꿈은 탐험가입니다."},{"who":"친구(생각)","text":"알맞은 크기의 목소리로 또박또박 이야기하네."},{"who":"남자아이","text":"탐험가가 되어 북극을 탐험해 보고 싶습니다."},{"who":"친구(생각)","text":"듣는 사람을 바라보며 말하네."},{"who":"친구(생각)","text":"허리를 펴고 바른 자세로 서서 발표하네."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_review_b#24','kor',1,2,'u3','','g1_2_kor_u3_review_b','unit_review','K1-2-u3-C5',4,'essay','teacher','『국어』 98쪽 그림일기를 고쳐 쓴다면 무엇을 어떻게 바꾸면 좋을지 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K1-2-u3-C5","difficulty":4,"kind":"essay","stem":"『국어』 98쪽 그림일기를 고쳐 쓴다면 무엇을 어떻게 바꾸면 좋을지 쓰세요.","answer_guide":{"answer":"예: 날씨를 쓰고, 기억에 남는 일 하나를 골라 누구와 무엇을 했는지와 느낌을 자세히 쓴다. — 둘 이상이면 맞아요.","scoring_points":["날씨를 쓰라고 했는가","기억에 남는 일 하나를 고르라고 했는가","느낌을 쓰라고 했는가"]},"explanation":["빠진 날씨부터 채워요.","늘 하는 일 대신 기억에 남는 일을 써요.","98쪽이에요."],"asset":{"type":"diary","date":"20○○년 10월 22일 화요일","weather":null,"picture":"🛏️😴","lines":["나는 오늘 아침에 일어나 밥을 먹고","학교에 가서 공부를 했다.","그리고 집에 와서 숙제를 하고 잤다."]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_review_b#25','kor',1,2,'u3','','g1_2_kor_u3_review_b','unit_review','K1-2-u3-C1',4,'essay','teacher','여러 사람 앞에서 바른 자세로 발표하는 방법을 두 가지 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K1-2-u3-C1","difficulty":4,"kind":"essay","stem":"여러 사람 앞에서 바른 자세로 발표하는 방법을 두 가지 쓰세요.","answer_guide":{"answer":"예: 허리를 펴고 바른 자세로 서서 말한다. / 듣는 사람을 바라보며 알맞은 크기의 목소리로 말한다. — 두 가지면 맞아요.","scoring_points":["방법을 두 가지 썼는가","바른 발표 자세와 맞는가","문장이 자연스러운가"]},"explanation":["허리 펴기·알맞은 목소리·바라보기가 있어요.","말끝을 흐리지 않는 것도 좋아요.","85쪽 2번이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_review_c#1','kor',1,2,'u3','','g1_2_kor_u3_review_c','unit_review','K1-2-u3-C1',1,'mc','auto','『국어』 106쪽 — 「바른 자세로 말하기」에 알맞은 것은?',ARRAY['K1-2-u3-X02','K1-2-u3-X03']::text[],false,'{"seq":1,"concept":"K1-2-u3-C1","difficulty":1,"kind":"mc","stem":"『국어』 106쪽 — 「바른 자세로 말하기」에 알맞은 것은?","options":[{"t":"듣는 사람을 바라본다","correct":true},{"t":"말하는 사람을 바라본다","mis":"K1-2-u3-X02"},{"t":"귀 기울여 듣는다","mis":"K1-2-u3-X03"}],"explanation":["말할 때에는 듣는 사람을 바라봐요.","말하는 사람을 바라보는 것은 들을 때예요.","106쪽 1번이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
