INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_review_c#10','kor',1,2,'u3','','g1_2_kor_u3_review_c','unit_review','K1-2-u3-C2',2,'mc','auto','『국어활동』 37쪽 — 선생님 말씀을 잘 들은 아이의 가방 속에 있을 물건은?',ARRAY['K1-2-u3-X04']::text[],false,'{"seq":10,"concept":"K1-2-u3-C2","difficulty":2,"kind":"mc","stem":"『국어활동』 37쪽 — 선생님 말씀을 잘 들은 아이의 가방 속에 있을 물건은?","options":[{"t":"돗자리와 물","correct":true},{"t":"공과 줄넘기","mis":"K1-2-u3-X04"},{"t":"장난감 자동차","mis":"K1-2-u3-X04"}],"explanation":["「돗자리와 물도 준비해 주세요.」라고 하셨어요.","집중해서 들어야 준비물을 챙길 수 있어요.","선생님 말씀을 다시 읽어요."],"asset":{"type":"speech","turns":[{"who":"선생님","text":"내일은 현장 체험 학습을 가죠? 준비물을 안내할 테니 집중해서 잘 들어요."},{"who":"아이","text":"선생님, 내일 과자 가지고 와도 돼요?"},{"who":"선생님","text":"쓰레기를 줄이려면 과자는 봉지째 가져오지 말고 통에 먹을 만큼만 담아 오세요."},{"who":"선생님","text":"그리고 돗자리와 물도 준비해 주세요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
