INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_review_c#15','kor',1,2,'u3','','g1_2_kor_u3_review_c','unit_review','K1-2-u3-C6',2,'blank','auto','『국어』 108쪽 — 「영수가 ◯◯ 꿉니다.」',ARRAY['K1-2-u3-X19']::text[],false,'{"seq":15,"concept":"K1-2-u3-C6","difficulty":2,"kind":"blank","stem":"『국어』 108쪽 — 「영수가 ◯◯ 꿉니다.」","options":[{"t":"꿈을","correct":true},{"t":"꿈이","mis":"K1-2-u3-X19"},{"t":"밤에","mis":"K1-2-u3-X19"}],"explanation":["「영수가 꿈을 꿉니다.」예요.","「밤에」는 언제예요.","108쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_review_c#16','kor',1,2,'u3','','g1_2_kor_u3_review_c','unit_review','K1-2-u3-C1',2,'ox','auto','발표하기 전에 말할 내용을 미리 생각하면 좋아요.',ARRAY['K1-2-u3-X03']::text[],false,'{"seq":16,"concept":"K1-2-u3-C1","difficulty":2,"kind":"ox","stem":"발표하기 전에 말할 내용을 미리 생각하면 좋아요.","answer":"O","reason_options":[{"t":"무엇을 말할지 정리하면 자신 있게 말할 수 있으니까","correct":true},{"t":"생각하지 않고 바로 말해야 더 잘하니까","mis":"K1-2-u3-X03"}],"mis":"K1-2-u3-X03","explanation":["남자아이도 꿈을 어떻게 소개할지 미리 생각했어요.","준비하면 자신감이 생겨요.","84쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_review_c#17','kor',1,2,'u3','','g1_2_kor_u3_review_c','unit_review','K1-2-u3-C2',3,'error','auto','친구가 발표할 때 「예쁜 그림을 그려야지.」 하며 그림을 그렸어요. 무엇이 잘못되었나요?',ARRAY['K1-2-u3-X04']::text[],false,'{"seq":17,"concept":"K1-2-u3-C2","difficulty":3,"kind":"error","stem":"친구가 발표할 때 「예쁜 그림을 그려야지.」 하며 그림을 그렸어요. 무엇이 잘못되었나요?","options":[{"t":"딴짓을 하면 말을 알아듣지 못해요 — 말하는 사람을 바라보며 들어요","correct":true,"mis_target":"K1-2-u3-X04"},{"t":"잘했어요","mis":"K1-2-u3-X04"},{"t":"그림을 더 빨리 그려야 해요","mis":"K1-2-u3-X04"}],"explanation":["딴짓하지 말고 들어야 해요.","바라보며 귀 기울여 들어요.","86쪽이에요."],"asset":{"type":"speech","turns":[{"who":"발표하는 친구","text":"제가 좋아하는 것은……."},{"who":"바라보며 듣는 친구(생각)","text":"친구가 좋아하는 건 뭘까?"},{"who":"짝에게 말하는 친구","text":"어제 말이야……."},{"who":"그림 그리는 친구(생각)","text":"예쁜 그림을 그려야지."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_review_c#18','kor',1,2,'u3','','g1_2_kor_u3_review_c','unit_review','K1-2-u3-C5',3,'error','auto','친구가 그림일기에 「준비물: 돗자리, 물」을 썼어요. 무엇이 잘못되었나요?',ARRAY['K1-2-u3-X12','K1-2-u3-X11']::text[],false,'{"seq":18,"concept":"K1-2-u3-C5","difficulty":3,"kind":"error","stem":"친구가 그림일기에 「준비물: 돗자리, 물」을 썼어요. 무엇이 잘못되었나요?","options":[{"t":"알려 주는 글에 들어갈 말이에요 — 내가 겪은 일과 느낌을 써요","correct":true,"mis_target":"K1-2-u3-X12"},{"t":"잘 썼어요","mis":"K1-2-u3-X12"},{"t":"날씨를 지워야 해요","mis":"K1-2-u3-X11"}],"explanation":["그림일기에는 내가 겪은 일을 써요.","준비물은 안내하는 글이에요.","107쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_review_c#19','kor',1,2,'u3','','g1_2_kor_u3_review_c','unit_review','K1-2-u3-C6',3,'error','auto','「영수가 꿉니다.」 무엇이 잘못되었나요?',ARRAY['K1-2-u3-X19']::text[],false,'{"seq":19,"concept":"K1-2-u3-C6","difficulty":3,"kind":"error","stem":"「영수가 꿉니다.」 무엇이 잘못되었나요?","options":[{"t":"「무엇을」에 해당하는 말이 빠졌어요 — 「영수가 꿈을 꿉니다.」","correct":true,"mis_target":"K1-2-u3-X19"},{"t":"잘 쓴 문장이에요","mis":"K1-2-u3-X19"},{"t":"「영수가」를 빼야 해요","mis":"K1-2-u3-X19"}],"explanation":["무엇을 꾸는지 「꿈을」을 넣어요.","「무엇을?」 하고 되물어 봐요.","108쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_review_c#20','kor',1,2,'u3','','g1_2_kor_u3_review_c','unit_review','K1-2-u3-C4',3,'error','auto','「슬펐던 일」 칸에 「생일 선물을 받은 일」을 썼어요. 무엇이 잘못되었나요?',ARRAY['K1-2-u3-X09']::text[],false,'{"seq":20,"concept":"K1-2-u3-C4","difficulty":3,"kind":"error","stem":"「슬펐던 일」 칸에 「생일 선물을 받은 일」을 썼어요. 무엇이 잘못되었나요?","options":[{"t":"기쁜 일이라 「재미있었던 일」에 넣어야 해요","correct":true,"mis_target":"K1-2-u3-X09"},{"t":"잘 넣었어요","mis":"K1-2-u3-X09"},{"t":"「놀랐던 일」에만 넣을 수 있어요","mis":"K1-2-u3-X09"}],"explanation":["일과 느낌이 맞아야 해요.","선물을 받으면 기뻐요.","93쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_review_c#21','kor',1,2,'u3','','g1_2_kor_u3_review_c','unit_review','K1-2-u3-C7',3,'ox','auto','전시된 친구 작품은 마음대로 만지거나 고쳐도 돼요.',ARRAY['K1-2-u3-X18']::text[],false,'{"seq":21,"concept":"K1-2-u3-C7","difficulty":3,"kind":"ox","stem":"전시된 친구 작품은 마음대로 만지거나 고쳐도 돼요.","answer":"X","reason_options":[{"t":"친구가 정성껏 만든 작품이니 눈으로 보고 좋은 점을 말해야 하니까","correct":true},{"t":"같은 반 친구 것이니 괜찮으니까","mis":"K1-2-u3-X18"}],"mis":"K1-2-u3-X18","explanation":["작품에 손대지 않아요.","좋았던 점을 말해요.","전시 예절이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_review_c#22','kor',1,2,'u3','','g1_2_kor_u3_review_c','unit_review','K1-2-u3-C5',3,'match','auto','『국어활동』 39쪽 — 그림일기 부분과 잘 쓰는 방법을 이어 보세요.','{}'::text[],false,'{"seq":22,"concept":"K1-2-u3-C5","difficulty":3,"kind":"match","stem":"『국어활동』 39쪽 — 그림일기 부분과 잘 쓰는 방법을 이어 보세요.","pairs":[{"l":"날씨","r":"「맑음」처럼 간단히 쓰거나 「눈이 와서 신나는 날」처럼 자세히 쓴다."},{"l":"그림","r":"경험한 일 가운데 가장 중요한 내용을 그린다."},{"l":"글","r":"가장 기억에 남는 내용과 생각이나 느낌을 쓴다."}],"mis":"K1-2-u3-X11","explanation":["날씨는 간단히 또는 자세히 써요.","그림은 가장 중요한 내용, 글은 기억에 남는 내용과 느낌이에요.","국어활동 39쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_review_c#23','kor',1,2,'u3','','g1_2_kor_u3_review_c','unit_review','K1-2-u3-C2',4,'sa','auto','『국어활동』 37쪽 — 선생님이 과자와 함께 준비하라고 한 것 가운데 깔고 앉는 것은 무엇인가요?','{}'::text[],false,'{"seq":23,"concept":"K1-2-u3-C2","difficulty":4,"kind":"sa","stem":"『국어활동』 37쪽 — 선생님이 과자와 함께 준비하라고 한 것 가운데 깔고 앉는 것은 무엇인가요?","answer":["돗자리"],"explanation":["돗자리와 물도 준비하라고 하셨어요.","끝까지 들어야 알 수 있어요.","국어활동 37쪽이에요."],"asset":{"type":"speech","turns":[{"who":"선생님","text":"내일은 현장 체험 학습을 가죠? 준비물을 안내할 테니 집중해서 잘 들어요."},{"who":"아이","text":"선생님, 내일 과자 가지고 와도 돼요?"},{"who":"선생님","text":"쓰레기를 줄이려면 과자는 봉지째 가져오지 말고 통에 먹을 만큼만 담아 오세요."},{"who":"선생님","text":"그리고 돗자리와 물도 준비해 주세요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_review_c#24','kor',1,2,'u3','','g1_2_kor_u3_review_c','unit_review','K1-2-u3-C6',4,'essay','teacher','「나는 오늘 친구와 인형 놀이를 했다. 참 재미있었다.」를 더 자세하게 고쳐 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K1-2-u3-C6","difficulty":4,"kind":"essay","stem":"「나는 오늘 친구와 인형 놀이를 했다. 참 재미있었다.」를 더 자세하게 고쳐 쓰세요.","answer_guide":{"answer":"예: 지아와 교실에서 인형 놀이를 했다. 인형에게 이름을 지어 주고 소꿉놀이를 하니 웃음이 났다. — 누구·어디·무엇이 어떻게 재미있었는지 들어가면 맞아요.","scoring_points":["누구와 어디에서를 썼는가","무엇을 어떻게 했는지 자세한가","버릇말 대신 느낌을 자세히 썼는가"]},"explanation":["「나는 오늘」, 「참 재미있었다」는 빼도 돼요.","무엇이 어떻게 재미있었는지 써요.","지도서 157쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_review_c#25','kor',1,2,'u3','','g1_2_kor_u3_review_c','unit_review','K1-2-u3-C2',4,'essay','teacher','지도서 169쪽 — 친구의 발표를 들을 때 지킬 바른 자세를 두 가지 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K1-2-u3-C2","difficulty":4,"kind":"essay","stem":"지도서 169쪽 — 친구의 발표를 들을 때 지킬 바른 자세를 두 가지 쓰세요.","answer_guide":{"answer":"예: 말하는 사람을 바라보며 듣는다. / 방해하지 않고 귀 기울여 듣는다. / 고개를 끄덕이거나 미소를 지으며 듣는다. — 두 가지면 맞아요.","scoring_points":["듣는 자세를 두 가지 썼는가","바른 듣기 자세와 맞는가","문장이 자연스러운가"]},"explanation":["바라보기·방해하지 않기·끄덕이기가 있어요.","떠들거나 딴짓하지 않아요.","듣기 점검표예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_review_d#1','kor',1,2,'u3','','g1_2_kor_u3_review_d','unit_review','K1-2-u3-C1',1,'mc','auto','『국어』 106쪽 — 「바른 자세로 말하기」에 알맞은 것은?',ARRAY['K1-2-u3-X03','K1-2-u3-X01']::text[],false,'{"seq":1,"concept":"K1-2-u3-C1","difficulty":1,"kind":"mc","stem":"『국어』 106쪽 — 「바른 자세로 말하기」에 알맞은 것은?","options":[{"t":"또박또박 말한다","correct":true},{"t":"귀 기울여 듣는다","mis":"K1-2-u3-X03"},{"t":"말끝을 흐린다","mis":"K1-2-u3-X01"}],"explanation":["말할 때에는 또박또박 말해요.","귀 기울여 듣는 것은 들을 때예요.","106쪽 1번이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_review_d#2','kor',1,2,'u3','','g1_2_kor_u3_review_d','unit_review','K1-2-u3-C2',1,'mc','auto','「어제 말이야…….」 하고 떠드는 친구에게 해 줄 말은?',ARRAY['K1-2-u3-X04','K1-2-u3-X05']::text[],false,'{"seq":2,"concept":"K1-2-u3-C2","difficulty":1,"kind":"mc","stem":"「어제 말이야…….」 하고 떠드는 친구에게 해 줄 말은?","options":[{"t":"시끄럽게 떠들면 안 돼.","correct":true},{"t":"나도 같이 이야기하자.","mis":"K1-2-u3-X04"},{"t":"너 정말 나빠!","mis":"K1-2-u3-X05"}],"explanation":["떠들면 여러 사람이 듣지 못해요.","나무라지 말고 친절하게 알려 줘요.","87쪽 (3)이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
