INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_review_d#8','kor',1,2,'u3','','g1_2_kor_u3_review_d','unit_review','K1-2-u3-C2',1,'mc','auto','『국어활동』 36쪽 — 선생님이 준비물을 안내할 때 바른 자세로 듣는 아이는?',ARRAY['K1-2-u3-X04']::text[],false,'{"seq":8,"concept":"K1-2-u3-C2","difficulty":1,"kind":"mc","stem":"『국어활동』 36쪽 — 선생님이 준비물을 안내할 때 바른 자세로 듣는 아이는?","options":[{"t":"선생님을 바라보며 집중해서 듣는 아이","correct":true},{"t":"엎드려 있는 아이","mis":"K1-2-u3-X04"},{"t":"과자를 먹고 있는 아이","mis":"K1-2-u3-X04"}],"explanation":["말하는 사람을 바라보며 들어요.","엎드리거나 딴짓하면 안내를 놓쳐요.","국어활동 36쪽이에요."],"asset":{"type":"speech","turns":[{"who":"선생님","text":"내일은 현장 체험 학습을 가죠? 준비물을 안내할 테니 집중해서 잘 들어요."},{"who":"아이","text":"선생님, 내일 과자 가지고 와도 돼요?"},{"who":"선생님","text":"쓰레기를 줄이려면 과자는 봉지째 가져오지 말고 통에 먹을 만큼만 담아 오세요."},{"who":"선생님","text":"그리고 돗자리와 물도 준비해 주세요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
