INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_review_d#13','kor',1,2,'u3','','g1_2_kor_u3_review_d','unit_review','K1-2-u3-C6',2,'mc','auto','『국어』 101쪽 — 「어떤 생각이나 느낌이 들었나요?」에 알맞은 대답은?',ARRAY['K1-2-u3-X07','K1-2-u3-X15']::text[],false,'{"seq":13,"concept":"K1-2-u3-C6","difficulty":2,"kind":"mc","stem":"『국어』 101쪽 — 「어떤 생각이나 느낌이 들었나요?」에 알맞은 대답은?","options":[{"t":"우리 편이 이겨서 기분이 좋았다.","correct":true},{"t":"운동회 날","mis":"K1-2-u3-X07"},{"t":"콩 주머니를 던졌다.","mis":"K1-2-u3-X15"}],"explanation":["기분이 좋았다는 느낌이에요.","운동회 날은 언제, 콩 주머니는 무슨 일이에요.","101쪽 물음이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
