INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_review_d#15','kor',1,2,'u3','','g1_2_kor_u3_review_d','unit_review','K1-2-u3-C6',2,'blank','auto','『국어』 108쪽 — 「황새가 ◯◯◯◯ 먹습니다.」',ARRAY['K1-2-u3-X19']::text[],false,'{"seq":15,"concept":"K1-2-u3-C6","difficulty":2,"kind":"blank","stem":"『국어』 108쪽 — 「황새가 ◯◯◯◯ 먹습니다.」","options":[{"t":"물고기를","correct":true},{"t":"물고기가","mis":"K1-2-u3-X19"},{"t":"물가에서","mis":"K1-2-u3-X19"}],"explanation":["「황새가 물고기를 먹습니다.」예요.","「물가에서」는 어디에서예요.","108쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_review_d#16','kor',1,2,'u3','','g1_2_kor_u3_review_d','unit_review','K1-2-u3-C3',2,'ox','auto','아침에 있었던 일이 떠오르지 않으면 내일 하고 싶은 일을 말해도 돼요.',ARRAY['K1-2-u3-X06']::text[],false,'{"seq":16,"concept":"K1-2-u3-C3","difficulty":2,"kind":"ox","stem":"아침에 있었던 일이 떠오르지 않으면 내일 하고 싶은 일을 말해도 돼요.","answer":"O","reason_options":[{"t":"「나는 내일 ○○에 가고 싶다.」처럼 말할 거리를 찾을 수 있으니까","correct":true},{"t":"아무 말도 하지 않는 것이 좋으니까","mis":"K1-2-u3-X06"}],"mis":"K1-2-u3-X06","explanation":["내일 하고 싶은 일로 말할 거리를 찾을 수 있어요.","문장 틀을 쓰면 쉬워요.","지도서 147쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_review_d#17','kor',1,2,'u3','','g1_2_kor_u3_review_d','unit_review','K1-2-u3-C2',3,'error','auto','떠드는 친구에게 「너 때문에 하나도 안 들리잖아!」라고 소리쳤어요. 무엇이 잘못되었나요?',ARRAY['K1-2-u3-X05','K1-2-u3-X04']::text[],false,'{"seq":17,"concept":"K1-2-u3-C2","difficulty":3,"kind":"error","stem":"떠드는 친구에게 「너 때문에 하나도 안 들리잖아!」라고 소리쳤어요. 무엇이 잘못되었나요?","options":[{"t":"나무라는 말 대신 「시끄럽게 떠들면 안 돼.」처럼 알려 줘요","correct":true,"mis_target":"K1-2-u3-X05"},{"t":"잘했어요 — 크게 혼내야 해요","mis":"K1-2-u3-X05"},{"t":"같이 떠들면 돼요","mis":"K1-2-u3-X04"}],"explanation":["조언하는 말은 친절하게 해요.","소리치면 발표가 더 방해돼요.","87쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_review_d#18','kor',1,2,'u3','','g1_2_kor_u3_review_d','unit_review','K1-2-u3-C5',3,'error','auto','친구가 날씨를 글의 맨 끝에 썼어요. 무엇이 잘못되었나요?',ARRAY['K1-2-u3-X11']::text[],false,'{"seq":18,"concept":"K1-2-u3-C5","difficulty":3,"kind":"error","stem":"친구가 날씨를 글의 맨 끝에 썼어요. 무엇이 잘못되었나요?","options":[{"t":"날씨는 맨 위 날짜와 요일 옆에 써요","correct":true,"mis_target":"K1-2-u3-X11"},{"t":"잘 썼어요","mis":"K1-2-u3-X11"},{"t":"날씨는 안 써도 돼요","mis":"K1-2-u3-X11"}],"explanation":["맨 윗줄에 날짜와 요일, 날씨를 써요.","자리를 지켜요.","96쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_review_d#19','kor',1,2,'u3','','g1_2_kor_u3_review_d','unit_review','K1-2-u3-C6',3,'error','auto','「공을 던지고 있는데 자꾸 끼어들었다.」 무엇이 부족한가요?',ARRAY['K1-2-u3-X16','K1-2-u3-X15']::text[],false,'{"seq":19,"concept":"K1-2-u3-C6","difficulty":3,"kind":"error","stem":"「공을 던지고 있는데 자꾸 끼어들었다.」 무엇이 부족한가요?","options":[{"t":"누가 어디에서 끼어들었는지가 빠졌어요","correct":true,"mis_target":"K1-2-u3-X16"},{"t":"잘 썼어요","mis":"K1-2-u3-X16"},{"t":"「참 재미있었다」를 덧붙여야 해요","mis":"K1-2-u3-X15"}],"explanation":["누가 끼어들었는지 알 수 없어요.","언제·어디에서·누구와를 써요.","지도서 157쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_review_d#20','kor',1,2,'u3','','g1_2_kor_u3_review_d','unit_review','K1-2-u3-C4',3,'error','auto','친구가 그림 색칠에만 시간을 다 써서 소개할 문장을 정하지 못했어요. 무엇이 잘못되었나요?',ARRAY['K1-2-u3-X10']::text[],false,'{"seq":20,"concept":"K1-2-u3-C4","difficulty":3,"kind":"error","stem":"친구가 그림 색칠에만 시간을 다 써서 소개할 문장을 정하지 못했어요. 무엇이 잘못되었나요?","options":[{"t":"그림은 무슨 일인지 보이면 돼요 — 문장으로 말할 것도 정해요","correct":true,"mis_target":"K1-2-u3-X10"},{"t":"잘했어요","mis":"K1-2-u3-X10"},{"t":"더 꼼꼼히 색칠해야 해요","mis":"K1-2-u3-X10"}],"explanation":["미술 활동이 아니에요.","무슨 일인지 문장으로 말해요.","지도서 150쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_review_d#21','kor',1,2,'u3','','g1_2_kor_u3_review_d','unit_review','K1-2-u3-C7',3,'mc','auto','친구 작품에서 무엇이 좋았는지 말한 것은?',ARRAY['K1-2-u3-X18','K1-2-u3-X08']::text[],false,'{"seq":21,"concept":"K1-2-u3-C7","difficulty":3,"kind":"mc","stem":"친구 작품에서 무엇이 좋았는지 말한 것은?","options":[{"t":"고양이가 웃는 얼굴이 재미있어.","correct":true},{"t":"그림을 못 그렸네.","mis":"K1-2-u3-X18"},{"t":"내 작품이 더 좋아.","mis":"K1-2-u3-X08"}],"explanation":["좋았던 점 한 가지를 짚어 말해요.","놀리거나 견주지 않아요.","감상 예절이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_review_d#22','kor',1,2,'u3','','g1_2_kor_u3_review_d','unit_review','K1-2-u3-C6',3,'match','auto','『국어』 100쪽 — 때와 있었던 일을 이어 보세요.','{}'::text[],false,'{"seq":22,"concept":"K1-2-u3-C6","difficulty":3,"kind":"match","stem":"『국어』 100쪽 — 때와 있었던 일을 이어 보세요.","pairs":[{"l":"아침","r":"늦잠 잔 일"},{"l":"낮","r":"선생님께 칭찬받은 일"},{"l":"저녁","r":"동생과 동화책을 읽은 일"}],"mis":"K1-2-u3-X14","explanation":["아침에는 늦잠, 낮에는 칭찬이에요.","저녁에는 동화책을 읽었어요.","100쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_review_d#23','kor',1,2,'u3','','g1_2_kor_u3_review_d','unit_review','K1-2-u3-C4',4,'sa','auto','『국어』 94쪽 — 우리는 농장에 가서 무엇을 만들었나요?','{}'::text[],false,'{"seq":23,"concept":"K1-2-u3-C4","difficulty":4,"kind":"sa","stem":"『국어』 94쪽 — 우리는 농장에 가서 무엇을 만들었나요?","answer":["치즈"],"explanation":["「우리는 농장에 가서 치즈를 만들었어.」라고 했어요.","어디에서 무엇을 했는지 드러나요.","94쪽이에요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"우리는 농장에 가서 치즈를 만들었어."},{"who":"친구 2","text":"민지가 전학을 갔어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_review_d#24','kor',1,2,'u3','','g1_2_kor_u3_review_d','unit_review','K1-2-u3-C6',4,'essay','teacher','『국어』 101쪽 — 어제 있었던 일 가운데 기억에 남는 일을 네 물음으로 정리해 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K1-2-u3-C6","difficulty":4,"kind":"essay","stem":"『국어』 101쪽 — 어제 있었던 일 가운데 기억에 남는 일을 네 물음으로 정리해 쓰세요.","answer_guide":{"answer":"예: 어제 저녁, 집에서 / 동생과 / 동화책을 읽었다 / 동생이 웃어서 뿌듯했다. — 네 가지가 들어가면 맞아요.","scoring_points":["언제·어디에서를 썼는가","누구와·무슨 일을 썼는가","생각이나 느낌을 썼는가"]},"explanation":["101쪽 네 물음에 답해요.","기억에 남는 일 하나를 골라요.","느낌도 꼭 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u3_review_d#25','kor',1,2,'u3','','g1_2_kor_u3_review_d','unit_review','K1-2-u3-C1',4,'essay','teacher','『국어』 90쪽 — 내가 발표한 모습을 돌아보고 잘한 점 하나와 고칠 점 하나를 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K1-2-u3-C1","difficulty":4,"kind":"essay","stem":"『국어』 90쪽 — 내가 발표한 모습을 돌아보고 잘한 점 하나와 고칠 점 하나를 쓰세요.","answer_guide":{"answer":"예: 잘한 점 — 허리를 펴고 섰다. / 고칠 점 — 말끝을 흐리지 않고 끝까지 말하겠다. — 잘한 점과 고칠 점이 하나씩 있으면 맞아요.","scoring_points":["잘한 점을 썼는가","고칠 점을 썼는가","남과 견주지 않고 내 발표를 돌아보았는가"]},"explanation":["90쪽 점검 물음으로 돌아봐요.","남과 견주지 않아요.","다음 발표에 고칠 점을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
